data.append({
    "instruction": "实现一个线程安全的日志系统，支持多线程写入文件，要求日志按日期和大小滚动，支持不同日志级别（DEBUG、INFO、WARNING、ERROR）",
    "input": "",
    "output": "让我来分析这个问题并逐步实现一个线程安全的日志系统。\n\n首先，思考需求分析：\n1. 线程安全：多个线程可以同时写入日志，不能出现内容错乱\n2. 文件滚动：按日期（每天一个新文件）和大小（超过指定大小创建新文件）\n3. 日志级别：DEBUG < INFO < WARNING < ERROR，可以设置输出级别过滤\n4. 性能考虑：频繁加锁可能影响性能，考虑使用异步写入\n\n设计思路：\n- 使用单例模式确保全局只有一个日志实例\n- 使用互斥锁保护文件写入操作\n- 使用条件变量实现异步日志队列\n- 后台线程负责实际写入文件，主线程只负责把日志放入队列\n\n关键问题和解决方案：\n1. 多线程竞争写入：使用生产者消费者模式\n2. 程序退出时刷新日志：析构函数通知后台线程退出并等待完成\n3. 格式化线程安全：使用ostringstream在栈上构建消息\n\n```cpp\n#include <iostream>\n#include <fstream>\n#include <string>\n#include <mutex>\n#include <queue>\n#include <thread>\n#include <condition_variable>\n#include <atomic>\n#include <sstream>\n#include <chrono>\n#include <iomanip>\n\nenum class LogLevel { DEBUG, INFO, WARNING, ERROR };\n\nclass Logger {\npublic:\n    static Logger& getInstance() {\n        static Logger instance;\n        return instance;\n    }\n    void setLogLevel(LogLevel level) { minLevel_ = level; }\n\n    template<typename... Args>\n    void log(LogLevel level, Args&&... args) {\n        if (level < minLevel_) return;\n        std::ostringstream oss;\n        (oss << ... << std::forward<Args>(args));\n        std::string msg = formatMessage(level, oss.str());\n        { std::lock_guard<std::mutex> lock(mtx_); logQueue_.push(std::move(msg)); }\n        cv_.notify_one();\n    }\n\n    ~Logger() {\n        running_ = false; cv_.notify_one();\n        if (writeThread_.joinable()) writeThread_.join();\n        if (file_.is_open()) file_.close();\n    }\n\nprivate:\n    Logger() : running_(true), minLevel_(LogLevel::DEBUG), maxSize_(10*1024*1024) {\n        openNewFile();\n        writeThread_ = std::thread(&Logger::writeLoop, this);\n    }\n    Logger(const Logger&) = delete;\n    Logger& operator=(const Logger&) = delete;\n\n    std::string formatMessage(LogLevel level, const std::string& msg) {\n        auto now = std::chrono::system_clock::now();\n        auto t = std::chrono::system_clock::to_time_t(now);\n        std::tm tm; localtime_s(&tm, &t);\n        auto ms = std::chrono::duration_cast<std::chrono::milliseconds>(now.time_since_epoch()) % 1000;\n        std::ostringstream oss;\n        oss << '[' << std::put_time(&tm, \"%Y-%m-%d %H:%M:%S\") << '.' << std::setfill('0') << std::setw(3) << ms.count() << \"] \";\n        const char* ls[] = {\"DEBUG\",\"INFO\",\"WARNING\",\"ERROR\"};\n        oss << '[' << ls[static_cast<int>(level)] << \"] [TID:\" << std::this_thread::get_id() << \"] \" << msg << '\\n';\n        return oss.str();\n    }\n\n    void openNewFile() {\n        if (file_.is_open()) file_.close();\n        auto now = std::chrono::system_clock::now();\n        auto t = std::chrono::system_clock::to_time_t(now);\n        std::tm tm; localtime_s(&tm, &t);\n        std::ostringstream fn;\n        fn << \"log_\" << std::put_time(&tm, \"%Y%m%d_%H%M%S\") << \".log\";\n        file_.open(fn.str(), std::ios::app);\n        curSize_ = 0;\n    }\n\n    void writeLoop() {\n        while (running_ || !logQueue_.empty()) {\n            std::string msg;\n            {\n                std::unique_lock<std::mutex> lock(mtx_);\n                cv_.wait(lock, [this]{ return !running_ || !logQueue_.empty(); });\n                if (!running_ && logQueue_.empty()) break;\n                msg = std::move(logQueue_.front()); logQueue_.pop();\n            }\n            if (curSize_ + msg.size() > maxSize_) openNewFile();\n            file_ << msg; file_.flush(); curSize_ += msg.size();\n        }\n    }\n\n    std::mutex mtx_;\n    std::condition_variable cv_;\n    std::queue<std::string> logQueue_;\n    std::thread writeThread_;\n    std::atomic<bool> running_;\n    std::ofstream file_;\n    std::size_t curSize_, maxSize_;\n    LogLevel minLevel_;\n};\n\n#define LOG_DEBUG(...) Logger::getInstance().log(LogLevel::DEBUG, __VA_ARGS__)\n#define LOG_INFO(...) Logger::getInstance().log(LogLevel::INFO, __VA_ARGS__)\n#define LOG_WARN(...) Logger::getInstance().log(LogLevel::WARNING, __VA_ARGS__)\n#define LOG_ERROR(...) Logger::getInstance().log(LogLevel::ERROR, __VA_ARGS__)\n\nint main() {\n    std::vector<std::thread> ts;\n    for (int i=0;i<3;++i) ts.emplace_back([i]{ for(int j=0;j<50;++j) LOG_INFO(\"线程\",i,\" 第\",j,\"条\"); });\n    for (auto& t:ts) t.join();\n    return 0;\n}\n```\n\n要点：Meyers单例、异步后台线程、条件变量、RAII锁管理。"
})

data.append({
    "instruction": "实现一个线程池，支持提交任意返回值类型的任务，返回future获取结果，支持动态调整线程数量",
    "input": "",
    "output": "我来实现一个功能完整的线程池。\n\n核心组件：工作线程集合、任务队列、互斥锁、条件变量、停止标志。\n\n关键设计点：\n1. 类型擦除：用std::packaged_task包装任务，配合shared_ptr解决不可复制问题\n2. submit返回future获取异步结果\n3. 动态扩容直接创建新线程，缩容通过原子计数器让线程自行退出\n4. 任务执行时提前释放锁，提高并发度\n\n```cpp\n#include <iostream>\n#include <vector>\n#include <queue>\n#include <thread>\n#include <mutex>\n#include <condition_variable>\n#include <future>\n#include <functional>\n#include <atomic>\n#include <stdexcept>\n#include <algorithm>\n\nclass ThreadPool {\npublic:\n    ThreadPool(size_t n = std::thread::hardware_concurrency()) : stop_(false), reduce_(0) {\n        if (n == 0) n = 4;\n        for (size_t i=0;i<n;++i) workers_.emplace_back(&ThreadPool::worker, this);\n    }\n\n    ~ThreadPool() {\n        { std::unique_lock<std::mutex> lock(mtx_); stop_ = true; }\n        cv_.notify_all();\n        for (auto& w : workers_) if (w.joinable()) w.join();\n    }\n\n    template<class F, class... Args>\n    auto submit(F&& f, Args&&... args) -> std::future<std::invoke_result_t<F, Args...>> {\n        using R = std::invoke_result_t<F, Args...>;\n        auto task = std::make_shared<std::packaged_task<R()>>(\n            std::bind(std::forward<F>(f), std::forward<Args>(args)...));\n        std::future<R> res = task->get_future();\n        {\n            std::unique_lock<std::mutex> lock(mtx_);\n            if (stop_) throw std::runtime_error(\"submit on stopped pool\");\n            tasks_.emplace([task]{ (*task)(); });\n        }\n        cv_.notify_one();\n        return res;\n    }\n\n    void resize(size_t n) {\n        std::unique_lock<std::mutex> lock(mtx_);\n        size_t cur = workers_.size();\n        if (n > cur) for (size_t i=0;i<n-cur;++i) workers_.emplace_back(&ThreadPool::worker, this);\n        else if (n < cur) { reduce_ = cur - n; cv_.notify_all(); }\n    }\n\nprivate:\n    void worker() {\n        for (;;) {\n            std::function<void()> task;\n            {\n                std::unique_lock<std::mutex> lock(mtx_);\n                cv_.wait(lock, [this]{ return stop_ || !tasks_.empty() || reduce_>0; });\n                if (reduce_>0) { --reduce_; auto it=std::find_if(workers_.begin(),workers_.end(),[](auto&t){return t.get_id()==std::this_thread::get_id();}); if(it!=workers_.end()){it->detach();workers_.erase(it);} return; }\n                if (stop_ && tasks_.empty()) return;\n                task = std::move(tasks_.front()); tasks_.pop();\n            }\n            task();\n        }\n    }\n\n    std::vector<std::thread> workers_;\n    std::queue<std::function<void()>> tasks_;\n    std::mutex mtx_;\n    std::condition_variable cv_;\n    std::atomic<bool> stop_;\n    std::atomic<size_t> reduce_;\n};\n\nint main() {\n    ThreadPool pool(4);\n    std::vector<std::future<int>> res;\n    for (int i=0;i<8;++i) res.push_back(pool.submit([i]{ return i*i; }));\n    for (auto& f:res) std::cout << f.get() << ' ';\n    return 0;\n}\n```\n\n要点：packaged_task+future实现异步结果、条件变量wait谓词防止虚假唤醒、正确的析构顺序保证任务完成。"
})

data.append({
    "instruction": "实现一个基于TCP的简单HTTP服务器，支持GET请求返回静态文件，多线程处理并发连接",
    "input": "",
    "output": "实现HTTP服务器需要考虑socket编程、HTTP协议解析、多线程并发、安全问题。\n\n核心流程：socket→bind→listen→accept→recv→解析→处理→send→close。\n\n关键问题：\n1. 跨平台兼容Windows/Linux socket差异\n2. TCP粘包：循环recv直到读到\\r\\n\\r\\n表示请求头结束\n3. 路径安全：防止../目录遍历攻击，用lexically_normal归一化路径\n4. sendAll：TCP可能一次发不完，循环发送所有数据\n\n```cpp\n#ifdef _WIN32\n#include <winsock2.h>\n#include <ws2tcpip.h>\n#pragma comment(lib,\"ws2_32.lib\")\n#else\n#include <sys/socket.h>\n#include <netinet/in.h>\n#include <arpa/inet.h>\n#include <unistd.h>\nusing SOCKET=int; constexpr SOCKET INVALID_SOCKET=-1; constexpr int SOCKET_ERROR=-1;\n#define closesocket close\n#endif\n#include <iostream>\n#include <fstream>\n#include <sstream>\n#include <thread>\n#include <filesystem>\n#include <unordered_map>\n\nnamespace fs=std::filesystem;\n\nbool sendAll(SOCKET s,const char*d,size_t l){\n    while(l>0){int sent=send(s,d,(int)l,0);if(sent==SOCKET_ERROR)return false;d+=sent;l-=sent;}\n    return true;\n}\n\nstd::string mime(const fs::path&p){\n    static std::unordered_map<std::string,std::string>m={\n        {\".html\",\"text/html;charset=utf-8\"},{\".css\",\"text/css\"},{\".js\",\"application/javascript\"},\n        {\".json\",\"application/json\"},{\".jpg\",\"image/jpeg\"},{\".png\",\"image/png\"},{\".txt\",\"text/plain\"}\n    };\n    auto it=m.find(p.extension().string());return it!=m.end()?it->second:\"application/octet-stream\";\n}\n\nvoid handle(SOCKET c,fs::path root){\n    char buf[8192];std::string req;\n    while(req.size()<sizeof(buf)){\n        int r=recv(c,buf,sizeof(buf)-1,0);if(r<=0){closesocket(c);return;}\n        buf[r]=0;req+=buf;if(req.find(\"\\r\\n\\r\\n\")!=std::string::npos)break;\n    }\n    std::istringstream ss(req);std::string method,path,ver;\n    ss>>method>>path>>ver;\n    std::string status,body,ct=\"text/plain\";\n    if(method!=\"GET\"){status=\"HTTP/1.1 405 Method Not Allowed\";body=\"405\";}\n    else{\n        if(path==\"/\"||path.empty())path=\"/index.html\";\n        fs::path fp=root/path.substr(1);fp=fp.lexically_normal();\n        if(fp.string().substr(0,root.string().size())!=root.string()){status=\"HTTP/1.1 403 Forbidden\";body=\"403\";}\n        else if(!fs::exists(fp)||!fs::is_regular_file(fp)){status=\"HTTP/1.1 404 Not Found\";body=\"404\";}\n        else{\n            std::ifstream f(fp,std::ios::binary);std::ostringstream bs;bs<<f.rdbuf();\n            body=bs.str();ct=mime(fp);status=\"HTTP/1.1 200 OK\";\n        }\n    }\n    std::ostringstream hs;\n    hs<<status<<\"\\r\\nContent-Type:\"<<ct<<\"\\r\\nContent-Length:\"<<body.size()<<\"\\r\\nConnection:close\\r\\n\\r\\n\";\n    std::string h=hs.str();\n    sendAll(c,h.data(),h.size());if(!body.empty())sendAll(c,body.data(),body.size());\n    closesocket(c);\n}\n\nint main(){\n#ifdef _WIN32\n    WSADATA wd;WSAStartup(MAKEWORD(2,2),&wd);\n#endif\n    fs::path root=fs::current_path()/\"www\";fs::create_directories(root);\n    std::ofstream(root/\"index.html\")<<\"<h1>Hello C++ HTTP Server!</h1>\";\n    SOCKET ls=socket(AF_INET,SOCK_STREAM,0);\n    int opt=1;setsockopt(ls,SOL_SOCKET,SO_REUSEADDR,(char*)&opt,sizeof(opt));\n    sockaddr_in addr{};addr.sin_family=AF_INET;addr.sin_port=htons(8080);addr.sin_addr.s_addr=INADDR_ANY;\n    bind(ls,(sockaddr*)&addr,sizeof(addr));listen(ls,SOMAXCONN);\n    std::cout<<\"Server on http://localhost:8080\\n\";\n    while(true){\n        sockaddr_in ca;int sz=sizeof(ca);\n        SOCKET c=accept(ls,(sockaddr*)&ca,&sz);\n        if(c!=INVALID_SOCKET)std::thread(handle,c,root).detach();\n    }\n    closesocket(ls);\n#ifdef _WIN32\n    WSACleanup();\n#endif\n}\n```\n\n要点：目录遍历防护、正确的Content-Type、跨平台socket封装。"
})

