data.append({
    "instruction": "文件锁实现多进程安全计数器：Windows用LockFileEx，Linux用flock，跨平台实现，RAII管理锁生命周期",
    "input": "",
    "output": "多进程同时操作文件需要文件锁防止竞态条件。典型的读-修改-写必须全程持有排他锁。\n\n设计要点：\n1. RAII封装：构造加锁、析构解锁，即使异常也不会死锁\n2. 跨平台：宏区分Windows/Linux API\n3. 二进制存储整数，固定4字节方便读写\n4. 读写前lseek到开头\n\n```cpp\n#ifdef _WIN32\n#include <windows.h>\n#else\n#include <fcntl.h>\n#include <unistd.h>\n#include <sys/file.h>\n#endif\n#include <iostream>\n\nclass FileLock{\npublic:\n#ifdef _WIN32\n    HANDLE h;\n    FileLock(const char*name){\n        h=CreateFileA(name,GENERIC_READ|GENERIC_WRITE,FILE_SHARE_READ|FILE_SHARE_WRITE,0,OPEN_ALWAYS,0,0);\n    }\n    ~FileLock(){if(h!=INVALID_HANDLE_VALUE)CloseHandle(h);}\n    void lock(){OVERLAPPED o={};LockFileEx(h,LOCKFILE_EXCLUSIVE_LOCK,0,MAXDWORD,MAXDWORD,&o);}\n    void unlock(){OVERLAPPED o={};UnlockFileEx(h,0,MAXDWORD,MAXDWORD,&o);}\n    bool readInt(int&v){DWORD r;SetFilePointer(h,0,0,FILE_BEGIN);return ReadFile(h,&v,4,&r,0)&&r==4;}\n    bool writeInt(int v){DWORD w;SetFilePointer(h,0,0,FILE_BEGIN);return WriteFile(h,&v,4,&w,0)&&w==4;}\n#else\n    int fd;\n    FileLock(const char*name){fd=open(name,O_RDWR|O_CREAT,0644);}\n    ~FileLock(){if(fd!=-1)close(fd);}\n    void lock(){flock(fd,LOCK_EX);}\n    void unlock(){flock(fd,LOCK_UN);}\n    bool readInt(int&v){lseek(fd,0,SEEK_SET);return read(fd,&v,4)==4;}\n    bool writeInt(int v){lseek(fd,0,SEEK_SET);return write(fd,&v,4)==4;}\n#endif\n};\n\nclass LockGuard{FileLock&fl;public:LockGuard(FileLock&f):fl(f){fl.lock();}~LockGuard(){fl.unlock();}};\n\nint main(){\n    for(int i=0;i<100;++i){\n        FileLock fl(\"counter.dat\");LockGuard g(fl);\n        int cnt=0;fl.readInt(cnt);fl.writeInt(cnt+1);\n    }\n    FileLock fl(\"counter.dat\");LockGuard g(fl);\n    int cnt=0;fl.readInt(cnt);std::cout<<\"count=\"<<cnt<<\"\\n\";\n    return 0;\n}\n```\n\n验证：同时启动3个进程，最终结果应为300。不加锁会小于300。进程崩溃时OS自动释放锁。"
})

data.append({
    "instruction": "内存映射文件：使用Windows MapViewOfFile或Linux mmap实现大文件的快速读写，统计大文本文件中单词出现频率",
    "input": "",
    "output": "内存映射文件把文件映射到进程地址空间，像操作内存一样操作文件，省去read/write系统调用，对大文件特别高效。\n\n工作原理：OS的虚拟内存管理，页面按需调页，多个进程可以共享同一物理页。\n\n关键步骤：打开文件→获取文件大小→创建映射→映射视图→操作指针→取消映射→关闭句柄。\n\n```cpp\n#ifdef _WIN32\n#include <windows.h>\n#else\n#include <sys/mman.h>\n#include <fcntl.h>\n#include <unistd.h>\n#include <sys/stat.h>\n#endif\n#include <iostream>\n#include <string>\n#include <unordered_map>\n#include <cctype>\n\nclass MemoryMappedFile{\npublic:\n#ifdef _WIN32\n    HANDLE hFile,hMap;char*data;SIZE_T size;\n\n    MemoryMappedFile(const char*name):hFile(INVALID_HANDLE_VALUE),hMap(NULL),data(nullptr),size(0){\n        hFile=CreateFileA(name,GENERIC_READ,FILE_SHARE_READ,0,OPEN_EXISTING,0,0);\n        if(hFile==INVALID_HANDLE_VALUE)return;\n        LARGE_INTEGER sz;GetFileSizeEx(hFile,&sz);size=sz.QuadPart;\n        hMap=CreateFileMappingA(hFile,0,PAGE_READONLY,0,0,0);\n        if(hMap)data=(char*)MapViewOfFile(hMap,FILE_MAP_READ,0,0,0);\n    }\n    ~MemoryMappedFile(){\n        if(data)UnmapViewOfFile(data);\n        if(hMap)CloseHandle(hMap);\n        if(hFile!=INVALID_HANDLE_VALUE)CloseHandle(hFile);\n    }\n#else\n    char*data;size_t size;int fd;\n    MemoryMappedFile(const char*name):data(MAP_FAILED),size(0),fd(-1){\n        fd=open(name,O_RDONLY);if(fd<0)return;\n        struct stat st;if(fstat(fd,&st)<0)return;\n        size=st.st_size;\n        data=(char*)mmap(0,size,PROT_READ,MAP_PRIVATE,fd,0);\n    }\n    ~MemoryMappedFile(){if(data!=MAP_FAILED)munmap(data,size);if(fd!=-1)close(fd);}\n#endif\n    bool valid()const{\n#ifdef _WIN32\n        return data!=nullptr;\n#else\n        return data!=MAP_FAILED;\n#endif\n    }\n};\n\nint main(int argc,char**argv){\n    const char*fname=argc>1?argv[1]:\"test.txt\";\n    std::ofstream(fname)<<\"hello world hello cplusplus memory mapped file world hello\";\n\n    MemoryMappedFile mmf(fname);\n    if(!mmf.valid()){std::cerr<<\"map failed\\n\";return 1;}\n\n    std::unordered_map<std::string,int>cnt;\n    std::string word;\n    for(size_t i=0;i<mmf.size;++i){\n        char c=mmf.data[i];\n        if(std::isalpha((unsigned char)c))word+=std::tolower((unsigned char)c);\n        else if(!word.empty()){cnt[word]++;word.clear();}\n    }\n    if(!word.empty())cnt[word]++;\n\n    for(auto&p:cnt)std::cout<<p.first<<\": \"<<p.second<<\"\\n\";\n    return 0;\n}\n```\n\n优势：\n1. 省去用户态/内核态数据拷贝\n2. OS按需分页，不用一次性读入整个文件\n3. 代码简洁，像访问数组一样访问文件内容\n注意：映射的页面对齐问题，Windows会自动处理。"
})

data.append({
    "instruction": "实现INI配置文件解析器：支持section、key=value、注释(;或#)，能够读取字符串、整数、浮点数，支持默认值",
    "input": "",
    "output": "INI文件是常见的配置格式，格式简单：[section]下的key=value对，注释以;或#开头。\n\n思考解析流程：\n1. 逐行读取，去掉前后空白\n2. 空行和注释行跳过\n3. [section]行进入新section\n4. key=value行，分割key和value\n5. 存储结构：unordered_map<section, unordered_map<key, value>>\n\n关键细节：\n- 大小写是否敏感？通常section和key不区分大小写，但value保留原样\n- value两边的空白要trim\n- 支持=前后有空格\n\n```cpp\n#include <iostream>\n#include <fstream>\n#include <string>\n#include <unordered_map>\n#include <sstream>\n#include <algorithm>\n\nclass IniParser{\n    std::string trim(const std::string&s){\n        auto a=s.find_first_not_of(\" \\t\\r\\n\");\n        if(a==std::string::npos)return\"\";\n        auto b=s.find_last_not_of(\" \\t\\r\\n\");\n        return s.substr(a,b-a+1);\n    }\n    std::string toLower(std::string s){\n        std::transform(s.begin(),s.end(),s.begin(),::tolower);return s;\n    }\npublic:\n    std::unordered_map<std::string,std::unordered_map<std::string,std::string>> data;\n\n    bool load(const std::string&filename){\n        std::ifstream f(filename);if(!f)return false;\n        std::string line,section=\"\";\n        while(std::getline(f,line)){\n            line=trim(line);\n            if(line.empty()||line[0]==';'||line[0]=='#')continue;\n            if(line[0]=='['&&line.back()==']'){\n                section=toLower(trim(line.substr(1,line.size()-2)));\n            }else{\n                auto eq=line.find('=');\n                if(eq==std::string::npos)continue;\n                std::string key=toLower(trim(line.substr(0,eq)));\n                std::string val=trim(line.substr(eq+1));\n                data[section][key]=val;\n            }\n        }\n        return true;\n    }\n\n    std::string get(const std::string&sec,const std::string&key,const std::string&def=\"\"){\n        auto s=data.find(toLower(sec));if(s==data.end())return def;\n        auto k=s->second.find(toLower(key));return k==s->second.end()?def:k->second;\n    }\n\n    int getInt(const std::string&sec,const std::string&key,int def=0){\n        std::string v=get(sec,key,\"\");if(v.empty())return def;\n        return std::stoi(v);\n    }\n\n    double getDouble(const std::string&sec,const std::string&key,double def=0.0){\n        std::string v=get(sec,key,\"\");if(v.empty())return def;\n        return std::stod(v);\n    }\n};\n\nint main(){\n    std::ofstream(\"test.ini\")<<\n        \"; 这是注释\\n\"\n        \"[server]\\n\"\n        \"host = 127.0.0.1\\n\"\n        \"port = 8080\\n\"\n        \"# 端口号\\n\"\n        \"debug = true\\n\"\n        \"[database]\\n\"\n        \"timeout = 30.5\\n\";\n\n    IniParser ini;ini.load(\"test.ini\");\n    std::cout<<\"host=\"<<ini.get(\"server\",\"host\")<<\"\\n\";\n    std::cout<<\"port=\"<<ini.getInt(\"server\",\"port\",80)<<\"\\n\";\n    std::cout<<\"timeout=\"<<ini.getDouble(\"database\",\"timeout\")<<\"\\n\";\n    std::cout<<\"missing=\"<<ini.get(\"a\",\"b\",\"default\")<<\"\\n\";\n    return 0;\n}\n```\n\n要点：trim函数处理空白、section/key统一小写实现大小写不敏感、类型转换带默认值容错。"
})

data.append({
    "instruction": "CSV文件处理器：读写CSV格式文件，处理引号转义、逗号嵌套、换行符等特殊情况，支持按列访问数据",
    "input": "",
    "output": "CSV看起来简单，但正确处理各种边界情况并不容易：\n- 字段包含逗号需要用双引号括起来：a,\"b,c\",d\n- 字段包含双引号需要用两个双引号转义：\"a\"\"b\"\n- 字段包含换行符也需要引号包裹\n\n不能简单地用split(',')！需要状态机解析。\n\n状态机设计：\n- 正常状态：遇到逗号→字段结束；遇到引号→进入引号状态；遇到换行→行结束\n- 引号状态：遇到引号→检查下一个字符：如果是引号则转义输出一个引号，如果是逗号/换行则退出引号状态；其他字符正常输出\n\n```cpp\n#include <iostream>\n#include <fstream>\n#include <vector>\n#include <string>\n#include <sstream>\n\nclass CsvReader{\npublic:\n    std::vector<std::vector<std::string>> rows;\n\n    bool load(const std::string&fn){\n        std::ifstream f(fn);if(!f)return false;\n        std::string line,field;char c;\n        bool inQuote=false;std::vector<std::string>row;\n        std::string content((std::istreambuf_iterator<char>(f)),std::istreambuf_iterator<char>());\n        content+='\\n';\n        for(size_t i=0;i<content.size();++i){\n            c=content[i];\n            if(inQuote){\n                if(c=='\"'){\n                    if(i+1<content.size()&&content[i+1]=='\"'){field+='\"';i++;}\n                    else inQuote=false;\n                }else field+=c;\n            }else{\n                if(c=='\"')inQuote=true;\n                else if(c==','){row.push_back(field);field.clear();}\n                else if(c=='\\n'||c=='\\r'){\n                    if(c=='\\r'&&i+1<content.size()&&content[i+1]=='\\n')i++;\n                    if(!field.empty()||!row.empty()){row.push_back(field);rows.push_back(row);}\n                    field.clear();row.clear();\n                }else field+=c;\n            }\n        }\n        return true;\n    }\n\n    size_t rowCount()const{return rows.size();}\n    size_t colCount()const{return rows.empty()?0:rows[0].size();}\n    std::string get(size_t r,size_t c,const std::string&def=\"\"){\n        if(r>=rows.size()||c>=rows[r].size())return def;\n        return rows[r][c];\n    }\n};\n\nclass CsvWriter{\n    std::ofstream f;\n    static std::string escape(const std::string&s){\n        if(s.find(',')!=std::string::npos||s.find('\"')!=std::string::npos||s.find('\\n')!=std::string::npos){\n            std::string out=\"\\\"\";\n            for(char c:s){if(c=='\"')out+=\"\\\"\\\"\";else out+=c;}\n            out+=\"\\\"\";return out;\n        }\n        return s;\n    }\npublic:\n    CsvWriter(const std::string&fn):f(fn){}\n    void writeRow(const std::vector<std::string>&row){\n        for(size_t i=0;i<row.size();++i){\n            if(i>0)f<<',';\n            f<<escape(row[i]);\n        }\n        f<<'\\n';\n    }\n};\n\nint main(){\n    {\n        CsvWriter w(\"test.csv\");\n        w.writeRow({\"name\",\"age\",\"note\"});\n        w.writeRow({\"张三\",\"25\",\"hello, world\"});\n        w.writeRow({\"李四\",\"30\",\"he said \\\"hi\\\"\"});\n    }\n    CsvReader r;r.load(\"test.csv\");\n    for(auto&row:r.rows){\n        for(auto&f:row)std::cout<<\"[\"<<f<<\"]\";\n        std::cout<<\"\\n\";\n    }\n    return 0;\n}\n```\n\n要点：状态机正确处理引号和转义、\\r\\n换行兼容、写入时自动判断是否需要引号包裹。简单的split(',')在真实数据中一定会出错。"
})

data.append({
    "instruction": "递归遍历目录：实现类似find命令的功能，列出目录下所有文件，支持按扩展名过滤、按文件大小过滤，输出文件路径和大小",
    "input": "",
    "output": "C++17引入了<filesystem>库，极大简化了文件系统操作。用std::filesystem::recursive_directory_iterator可以方便地递归遍历。\n\n思考要点：\n1. 错误处理：权限不足等可能抛出异常，用error_code重载避免异常\n2. 跳过符号链接避免循环？可以指定directory_options\n3. 过滤条件：文件扩展名、文件大小范围\n4. 可以计算目录总大小\n\n```cpp\n#include <iostream>\n#include <filesystem>\n#include <vector>\n#include <string>\n#include <iomanip>\n\nnamespace fs=std::filesystem;\n\nstruct FileInfo{\n    fs::path path;\n    uintmax_t size;\n};\n\nstd::vector<FileInfo> findFiles(const fs::path&root,\n                                const std::string&ext=\"\",\n                                uintmax_t minSize=0,\n                                uintmax_t maxSize=UINTMAX_MAX,\n                                bool recursive=true){\n    std::vector<FileInfo> result;\n    std::error_code ec;\n    auto it=recursive?fs::recursive_directory_iterator(root,fs::directory_options::skip_permission_denied,ec)\n                     :fs::directory_iterator(root,ec);\n    if(ec)return result;\n\n    for(const auto&entry:it){\n        if(!entry.is_regular_file(ec))continue;\n        uintmax_t sz=entry.file_size(ec);\n        if(ec)continue;\n        if(sz<minSize||sz>maxSize)continue;\n        if(!ext.empty()&&entry.path().extension()!=ext)continue;\n        result.push_back({entry.path(),sz});\n    }\n    return result;\n}\n\nstd::string humanSize(uintmax_t bytes){\n    const char*units[]={\"B\",\"KB\",\"MB\",\"GB\"};\n    int u=0;double s=bytes;\n    while(s>=1024&&u<3){s/=1024;u++;}\n    std::ostringstream os;os<<std::fixed<<std::setprecision(2)<<s<<units[u];\n    return os.str();\n}\n\nint main(int argc,char**argv){\n    fs::path dir=argc>1?argv[1]:\".\";\n    auto files=findFiles(dir,\".cpp\",0);\n    uintmax_t total=0;\n    for(auto&f:files){\n        std::cout<<std::left<<std::setw(10)<<humanSize(f.size)<<f.path.string()<<\"\\n\";\n        total+=f.size;\n    }\n    std::cout<<\"\\n共\"<<files.size()<<\"个文件，总大小\"<<humanSize(total)<<\"\\n\";\n    return 0;\n}\n```\n\nfilesystem要点：\n1. 使用error_code重载，遇到权限问题不崩溃\n2. directory_options::skip_permission_denied跳过无权限目录\n3. is_regular_file过滤掉目录、符号链接等\n4. recursive_directory_iterator自动递归，也可以手动控制depth\n5. path类重载了/运算符方便路径拼接"
})

data.append({
    "instruction": "文件复制工具：实现带进度显示的文件复制，支持大文件分块读写，处理复制中断（简单断点续传，检测目标文件已存在且大小匹配则跳过）",
    "input": "",
    "output": "复制文件看起来简单，但要做好需要考虑：\n1. 大文件不能一次性读入内存，需要分块（比如64KB或1MB一块）\n2. 二进制模式打开，否则换行转换会出问题\n3. 进度显示：已复制大小/总大小，百分比\n4. 简单断点续传：目标存在且大小和源文件相同则跳过；如果目标较小则从断点继续\n5. 错误处理：磁盘满、权限不足等\n\n```cpp\n#include <iostream>\n#include <fstream>\n#include <filesystem>\n#include <iomanip>\n#include <chrono>\n#include <cmath>\n\nnamespace fs=std::filesystem;\n\nbool copyFile(const fs::path&src,const fs::path&dst,bool showProgress=true){\n    std::error_code ec;\n    uintmax_t srcSize=fs::file_size(src,ec);\n    if(ec){std::cerr<<\"无法获取源文件大小\\n\";return false;}\n\n    uintmax_t existing=0;\n    if(fs::exists(dst,ec)){\n        existing=fs::file_size(dst,ec);\n        if(existing==srcSize){\n            std::cout<<\"文件已存在且大小一致，跳过: \"<<dst.filename()<<\"\\n\";\n            return true;\n        }\n        if(existing>srcSize)existing=0;\n    }\n\n    std::ifstream in(src,std::ios::binary);\n    std::ofstream out(dst,std::ios::binary|(existing>0?std::ios::app:std::ios::trunc));\n    if(!in||!out){std::cerr<<\"无法打开文件\\n\";return false;}\n\n    if(existing>0)in.seekg(existing);\n\n    const size_t BUF_SIZE=1024*1024;\n    std::vector<char>buf(BUF_SIZE);\n    uintmax_t copied=existing;\n    auto t0=std::chrono::steady_clock::now();\n\n    while(in){\n        in.read(buf.data(),BUF_SIZE);\n        std::streamsize n=in.gcount();\n        if(n>0)out.write(buf.data(),n);\n        copied+=n;\n\n        if(showProgress){\n            double pct=srcSize>0?(double)copied/srcSize*100:0;\n            auto t1=std::chrono::steady_clock::now();\n            double sec=std::chrono::duration<double>(t1-t0).count();\n            double speed=sec>0?(copied-existing)/sec/1024/1024:0;\n            std::cout<<\"\\r\"<<std::fixed<<std::setprecision(1)<<std::setw(5)<<pct<<\"% \"\n                     <<std::setw(8)<<(copied/1024/1024)<<\"/\"<<(srcSize/1024/1024)<<\"MB \"\n                     <<std::setw(6)<<speed<<\"MB/s\"<<std::flush;\n        }\n    }\n\n    if(showProgress)std::cout<<\"\\n完成\\n\";\n    return true;\n}\n\nint main(){\n    std::ofstream big(\"bigfile.bin\");\n    std::vector<char>d(1024*1024,0);\n    for(int i=0;i<10;++i)big.write(d.data(),d.size());\n    big.close();\n\n    copyFile(\"bigfile.bin\",\"bigfile_copy.bin\");\n    copyFile(\"bigfile.bin\",\"bigfile_copy.bin\");\n    return 0;\n}\n```\n\n要点：分块复制、断点续传通过seekg+app模式实现、实时进度和速度计算。注意gcount()必须在read之后调用获取实际读取字节数。"
})

