data.append({
    "instruction": "生产者消费者模型：实现一个多生产者多消费者的线程安全队列，支持阻塞等待、超时获取、有界队列（满时阻塞生产者）",
    "input": "",
    "output": "生产者消费者是并发编程经典问题，核心是：\n1. 队列空时消费者阻塞等待\n2. 队列满时生产者阻塞等待（有界队列）\n3. 使用条件变量实现等待/通知，避免忙等\n4. 注意notify_all vs notify_one，防止惊群\n\n设计：\n- 两个条件变量：notFull（生产者等待）、notEmpty（消费者等待）\n- mutex保护队列\n- 环形队列或者list/queue都可以\n\n```cpp\n#include <iostream>\n#include <queue>\n#include <thread>\n#include <mutex>\n#include <condition_variable>\n#include <chrono>\n#include <atomic>\n\ntemplate<typename T>\nclass BlockingQueue{\n    std::queue<T> q_;\n    mutable std::mutex mtx_;\n    std::condition_variable notFull_;\n    std::condition_variable notEmpty_;\n    size_t capacity_;\n    std::atomic<bool> closed_{false};\n\npublic:\n    explicit BlockingQueue(size_t cap):capacity_(cap){}\n\n    void close(){\n        {std::lock_guard<std::mutex>l(mtx_);closed_=true;}\n        notFull_.notify_all();notEmpty_.notify_all();\n    }\n\n    bool push(T v){\n        std::unique_lock<std::mutex>l(mtx_);\n        notFull_.wait(l,[this]{return closed_||q_.size()<capacity_;});\n        if(closed_&&q_.empty())return false;\n        q_.push(std::move(v));\n        notEmpty_.notify_one();\n        return !closed_;\n    }\n\n    bool pop(T&out){\n        std::unique_lock<std::mutex>l(mtx_);\n        notEmpty_.wait(l,[this]{return closed_||!q_.empty();});\n        if(q_.empty())return false;\n        out=std::move(q_.front());q_.pop();\n        notFull_.notify_one();\n        return true;\n    }\n\n    template<class Rep,class Period>\n    bool popFor(T&out,const std::chrono::duration<Rep,Period>&timeout){\n        std::unique_lock<std::mutex>l(mtx_);\n        if(!notEmpty_.wait_for(l,timeout,[this]{return closed_||!q_.empty();}))\n            return false;\n        if(q_.empty())return false;\n        out=std::move(q_.front());q_.pop();\n        notFull_.notify_one();\n        return true;\n    }\n\n    size_t size()const{\n        std::lock_guard<std::mutex>l(mtx_);return q_.size();\n    }\n};\n\nint main(){\n    BlockingQueue<int>q(5);\n    std::atomic<int>produced{0},consumed{0};\n\n    std::vector<std::thread>producers;\n    for(int i=0;i<2;++i)producers.emplace_back([&q,&produced,i]{\n        for(int j=0;j<10;++j){\n            q.push(i*100+j);produced++;\n            std::this_thread::sleep_for(std::chrono::milliseconds(10));\n        }\n    });\n\n    std::vector<std::thread>consumers;\n    for(int i=0;i<3;++i)consumers.emplace_back([&q,&consumed,i]{\n        int v;\n        while(q.pop(v)){\n            std::cout<<\"消费者\"<<i<<\" 拿到\"<<v<<\"\\n\";\n            consumed++;\n        }\n    });\n\n    for(auto&t:producers)t.join();\n    q.close();\n    for(auto&t:consumers)t.join();\n    std::cout<<\"生产\"<<produced<<\" 消费\"<<consumed<<\"\\n\";\n    return 0;\n}\n```\n\n要点：\n1. wait必须带谓词防止虚假唤醒\n2. 生产者用notify_one，没必要唤醒所有\n3. close()优雅关闭，通知所有等待线程退出\n4. wait_for实现超时获取\n5. 队列有界防止内存无限增长（生产快于消费时）"
})

data.append({
    "instruction": "读写锁实现线程安全缓存：使用std::shared_mutex（C++17），读操作共享锁，写操作排他锁，实现一个简单的键值缓存",
    "input": "",
    "output": "读写锁适用于读多写少的场景。多个读线程可以同时持有共享锁，写线程必须独占锁，这样比普通mutex读并发度高很多。\n\nC++17提供了std::shared_mutex和std::shared_lock：\n- 锁定共享（读）：shared_lock<shared_mutex>\n- 锁定排他（写）：unique_lock<shared_mutex> 或 lock_guard\n\n思考：缓存需要get/put/remove操作。get是读，put和remove是写。还可以加个clear。\n\n另外思考缓存失效：比如加TTL（过期时间），但先实现基本功能。\n\n```cpp\n#include <iostream>\n#include <unordered_map>\n#include <string>\n#include <shared_mutex>\n#include <mutex>\n#include <optional>\n#include <thread>\n#include <vector>\n#include <chrono>\n\ntemplate<typename K,typename V>\nclass ThreadSafeCache{\n    mutable std::shared_mutex mtx_;\n    std::unordered_map<K,V> data_;\n\npublic:\n    std::optional<V> get(const K&key)const{\n        std::shared_lock<std::shared_mutex>l(mtx_);\n        auto it=data_.find(key);\n        if(it==data_.end())return std::nullopt;\n        return it->second;\n    }\n\n    void put(const K&key,V val){\n        std::unique_lock<std::shared_mutex>l(mtx_);\n        data_[key]=std::move(val);\n    }\n\n    bool remove(const K&key){\n        std::unique_lock<std::shared_mutex>l(mtx_);\n        return data_.erase(key)>0;\n    }\n\n    bool contains(const K&key)const{\n        std::shared_lock<std::shared_mutex>l(mtx_);\n        return data_.count(key)>0;\n    }\n\n    size_t size()const{\n        std::shared_lock<std::shared_mutex>l(mtx_);\n        return data_.size();\n    }\n};\n\nint main(){\n    ThreadSafeCache<std::string,int>cache;\n    cache.put(\"a\",1);cache.put(\"b\",2);\n\n    std::vector<std::thread>readers;\n    for(int i=0;i<5;++i)readers.emplace_back([&cache,i]{\n        for(int j=0;j<100;++j){\n            auto v=cache.get(\"a\");\n            if(v)std::cout<<\"读\"<<i<<\": a=\"<<*v<<\"\\n\";\n            std::this_thread::sleep_for(std::chrono::milliseconds(1));\n        }\n    });\n\n    std::thread writer([&cache]{\n        for(int i=0;i<10;++i){\n            cache.put(\"counter\",i);\n            std::this_thread::sleep_for(std::chrono::milliseconds(50));\n        }\n    });\n\n    for(auto&t:readers)t.join();writer.join();\n    std::cout<<\"最终大小:\"<<cache.size()<<\"\\n\";\n    return 0;\n}\n```\n\n要点：\n1. mutable允许const成员函数（如get）加锁，因为锁是内部状态不影响逻辑常量性\n2. shared_lock用于读，允许多个读者并发\n3. unique_lock用于写，独占访问\n4. std::optional（C++17）优雅表示值可能不存在\n5. 适用于读频率远高于写的场景，如配置缓存、字典查询"
})

data.append({
    "instruction": "使用std::atomic实现无锁栈（Lock-free Stack），理解内存序（memory order）和ABA问题",
    "input": "",
    "output": "无锁数据结构不用mutex，通过原子操作实现并发访问，性能更高但实现复杂。\n\n无锁栈通常用链表实现，头指针是atomic<Node*>。push操作：创建新节点，新节点next指向当前头，然后CAS把head从旧头换成新节点。pop操作：读head，CAS把head换成head->next。\n\nABA问题：线程1读head=A，准备CAS(A→A.next)；线程2pop出A，又push入B、C、A；这时head又是A，线程1CAS成功，但A.next已经不是原来的next了，链表会被破坏。\n\n解决ABA： tagged pointer（标签+指针）或者 hazard pointer（危险指针延迟释放）。简单起见用带标签的原子（利用指针对齐，低位存标签）。\n\n内存序：原子操作默认seq_cst最安全，但可以用更松的内存序提高性能。push需要release，pop需要acquire。\n\n```cpp\n#include <iostream>\n#include <atomic>\n#include <thread>\n#include <vector>\n#include <optional>\n\ntemplate<typename T>\nclass LockFreeStack{\n    struct Node{T val;Node*next;Node(T v):val(std::move(v)),next(nullptr){}};\n\n    struct TaggedPtr{\n        Node*ptr;uintptr_t tag;\n        TaggedPtr():ptr(nullptr),tag(0){}\n        TaggedPtr(Node*p,uintptr_t t):ptr(p),tag(t){}\n        bool operator==(const TaggedPtr&o)const{return ptr==o.ptr&&tag==o.tag;}\n    };\n\n    std::atomic<TaggedPtr>head_;\n\npublic:\n    LockFreeStack(){head_.store(TaggedPtr(),std::memory_order_relaxed);}\n\n    ~LockFreeStack(){\n        TaggedPtr h=head_.load(std::memory_order_relaxed);\n        while(h.ptr){Node*t=h.ptr;h=t->next;delete t;}\n    }\n\n    void push(T v){\n        Node*n=new Node(std::move(v));\n        TaggedPtr old=head_.load(std::memory_order_relaxed);\n        TaggedPtr neo;\n        do{\n            n->next=old.ptr;\n            neo=TaggedPtr(n,old.tag+1);\n        }while(!head_.compare_exchange_weak(old,neo,std::memory_order_release,std::memory_order_relaxed));\n    }\n\n    std::optional<T>pop(){\n        TaggedPtr old=head_.load(std::memory_order_acquire);\n        TaggedPtr neo;\n        do{\n            if(!old.ptr)return std::nullopt;\n            neo=TaggedPtr(old.ptr->next,old.tag+1);\n        }while(!head_.compare_exchange_weak(old,neo,std::memory_order_acq_rel,std::memory_order_acquire));\n        T val=std::move(old.ptr->val);\n        delete old.ptr;\n        return val;\n    }\n};\n\nint main(){\n    LockFreeStack<int>stack;\n    std::vector<std::thread>threads;\n    for(int i=0;i<4;++i){\n        threads.emplace_back([&stack,i]{\n            for(int j=0;j<100;++j)stack.push(i*100+j);\n        });\n    }\n    for(auto&t:threads)t.join();\n    int count=0;std::optional<int>v;\n    while((v=stack.pop())){count++;}\n    std::cout<<\"弹出\"<<count<<\"个元素(应为400)\\n\";\n    return 0;\n}\n```\n\n内存序说明：\n- compare_exchange_weak可能虚假失败（spurious failure），所以必须循环，它比strong更快\n- push成功时用memory_order_release：保证之前的写入（n->next）对其他线程可见\n- pop加载时用memory_order_acquire：保证看到release之前的所有写入\n- tag解决ABA问题：即使ptr相同tag不同，CAS也会失败\n\n注意：这里的tag可能回绕（wrap around），实际生产中用hazard pointer更安全。无锁编程非常容易出错，除非性能关键否则优先用mutex。"
})

data.append({
    "instruction": "使用std::future和std::promise实现异步任务流水线：多个异步任务串联，前一个任务的输出是后一个任务的输入",
    "input": "",
    "output": "std::promise和std::future是C++线程间传递结果的机制：promise.set_value()设置结果，future.get()阻塞等待结果。\n\n流水线（pipeline）模式：任务A→任务B→任务C，数据依次流过每个阶段。每个阶段可以在不同线程上运行。\n\n思考实现方式：\n1. then式延续：但C++标准目前没有.then()（C++23可能有），需要手动实现\n2. 每个阶段的输出promise作为下一阶段的输入future\n3. 可以封装一个then函数，返回新的future\n\n```cpp\n#include <iostream>\n#include <future>\n#include <thread>\n#include <chrono>\n#include <string>\n\ntemplate<typename F,typename T>\nauto then(std::future<T>&f,F&&func)->std::future<decltype(func(f.get()))>{\n    return std::async(std::launch::async,[&f,func=std::forward<F>(func)]()mutable{\n        return func(f.get());\n    });\n}\n\nint main(){\n    std::promise<int>p;\n    std::future<int>f=p.get_future();\n\n    auto f2=then(f,[](int x){\n        std::cout<<\"阶段1: 接收\"<<x<<\"，加10\\n\";\n        std::this_thread::sleep_for(std::chrono::milliseconds(100));\n        return x+10;\n    });\n\n    auto f3=then(f2,[](int x){\n        std::cout<<\"阶段2: 接收\"<<x<<\"，乘2\\n\";\n        std::this_thread::sleep_for(std::chrono::milliseconds(100));\n        return x*2;\n    });\n\n    auto f4=then(f3,[](int x){\n        std::cout<<\"阶段3: 接收\"<<x<<\"，转字符串\\n\";\n        return \"结果是: \"+std::to_string(x);\n    });\n\n    std::thread producer([&p]{\n        std::this_thread::sleep_for(std::chrono::milliseconds(200));\n        std::cout<<\"生产初始值: 5\\n\";\n        p.set_value(5);\n    });\n\n    std::string res=f4.get();\n    std::cout<<res<<\"\\n\";\n\n    producer.join();\n\n    std::cout<<\"\\n=== packaged_task和async示例 ===\\n\";\n    auto add=[](int a,int b){return a+b;};\n    std::packaged_task<int(int,int)>task(add);\n    std::future<int>resF=task.get_future();\n    std::thread t(std::move(task),3,4);\n    std::cout<<\"3+4=\"<<resF.get()<<\"\\n\";\n    t.join();\n\n    auto fut=std::async(std::launch::async,[]{\n        std::this_thread::sleep_for(std::chrono::milliseconds(50));\n        return std::string(\"hello async\");\n    });\n    std::cout<<fut.get()<<\"\\n\";\n\n    return 0;\n}\n```\n\n要点：\n1. promise/future是一次性的，set_value只能调用一次\n2. std::async自动创建线程运行函数，返回future\n3. std::packaged_task把可调用对象包装成可以异步获取结果的任务，可以移动到线程\n4. then的实现利用std::launch::async创建新线程执行延续任务\n5. future.get()是阻塞等待，多次调用get()是未定义行为\n6. 流水线的每个阶段都是并行准备好的，一旦上游数据到达立即执行\n\n注意：std::launch::async vs std::launch::deferred：deferred是惰性求值，get时才在当前线程执行。默认策略是系统选择。"
})

data.append({
    "instruction": "交替打印ABC：三个线程分别打印A、B、C，要求输出必须按ABCABC...顺序循环打印10次，使用条件变量和原子变量两种方法实现",
    "input": "",
    "output": "这是经典的线程同步问题，考察对条件变量、线程间通信的理解。\n\n分析：三个线程需要协调执行顺序。线程A打印完通知B，B打印完通知C，C打印完通知A，循环。需要一个共享变量表示当前该哪个线程打印。\n\n方法一：条件变量\n- 用int turn=0表示当前轮到谁（0=A,1=B,2=C）\n- 每个线程循环：wait直到turn是自己，打印，设置turn，notify_all\n\n方法二：原子变量\n- 用atomic<int> turn，自旋等待（但这样浪费CPU，可以加yield）\n\n先实现条件变量版本，更高效（睡眠等待）：\n\n```cpp\n#include <iostream>\n#include <thread>\n#include <mutex>\n#include <condition_variable>\n#include <atomic>\n\nvoid printABC_CV(int rounds){\n    std::mutex mtx;\n    std::condition_variable cv;\n    int turn=0;\n\n    auto printChar=[&](char c,int myTurn){\n        for(int i=0;i<rounds;++i){\n            std::unique_lock<std::mutex>l(mtx);\n            cv.wait(l,[&]{return turn==myTurn;});\n            std::cout<<c;\n            turn=(turn+1)%3;\n            cv.notify_all();\n        }\n    };\n\n    std::thread t1(printChar,'A',0);\n    std::thread t2(printChar,'B',1);\n    std::thread t3(printChar,'C',2);\n    t1.join();t2.join();t3.join();\n    std::cout<<\"\\n\";\n}\n\nvoid printABC_Atomic(int rounds){\n    std::atomic<int>turn{0};\n\n    auto printChar=[&](char c,int myTurn){\n        for(int i=0;i<rounds;++i){\n            while(turn.load(std::memory_order_acquire)!=myTurn){\n                std::this_thread::yield();\n            }\n            std::cout<<c;\n            turn.store((myTurn+1)%3,std::memory_order_release);\n        }\n    };\n\n    std::thread t1(printChar,'A',0);\n    std::thread t2(printChar,'B',1);\n    std::thread t3(printChar,'C',2);\n    t1.join();t2.join();t3.join();\n    std::cout<<\"\\n\";\n}\n\nint main(){\n    std::cout<<\"条件变量版本: \";printABC_CV(5);\n    std::cout<<\"原子变量版本: \";printABC_Atomic(5);\n    return 0;\n}\n```\n\n思考为什么notify_all而不是notify_one？\n因为turn每次只改变1，比如A执行完turn=1，只有B在等turn=1，如果notify_one刚好唤醒了C（C在等turn=2），那C唤醒后检查turn不满足又会睡眠，但A已经执行完不会再notify了！这就会死锁。哦不对，等等——每个线程wait之后打印完都会notify_all，所以不会丢。但是如果用notify_one，可能唤醒的不是该打印的线程，该线程永远等不到通知。所以用notify_all安全。或者更精确：每个线程知道下一个是谁，可以notify_one？但要维护线程间的通知关系比较麻烦。notify_all虽然会有\"惊群\"，但这里只有3个线程无所谓。\n\n原子变量版本要点：\n- 自旋+yield：循环检查turn，不满足就yield让出CPU，比纯忙等高效\n- memory_order_acquire/release保证可见性和顺序\n\n条件变量版本要点：\n- wait必须带谓词，防止虚假唤醒\n- 锁保护turn的读写\n- 每个线程打印完一定要notify"
})

data.append({
    "instruction": "线程局部存储（thread_local）：使用thread_local实现每个线程独立的随机数生成器、错误码存储，演示TLS的用法",
    "input": "",
    "output": "thread_local是C++11引入的存储期说明符，每个线程有独立的变量实例。适合存线程独有的状态：随机数引擎、错误缓冲区、内存池、线程ID缓存等。\n\n思考thread_local vs __declspec(thread)（MSVC）/__thread（GCC）：前者是标准C++，后者是编译器扩展。thread_local支持动态初始化和析构（可以是类类型，有构造析构），而__thread通常只支持POD类型。\n\n常见用途：\n1. 每个线程独立的随机引擎，避免多线程竞争一个引擎，也不用加锁\n2. 线程独立的错误信息/日志上下文\n3. 线程独立的内存分配器（减少锁竞争）\n\n```cpp\n#include <iostream>\n#include <thread>\n#include <random>\n#include <string>\n#include <vector>\n\nthread_local std::mt19937 rng{std::random_device{}()};\nthread_local std::string lastError;\nthread_local int threadLocalCounter=0;\n\nvoid setError(const std::string&err){lastError=err;}\nstd::string getError(){return lastError;}\n\nint randomInt(int min,int max){\n    std::uniform_int_distribution<int>dist(min,max);\n    return dist(rng);\n}\n\nvoid threadWork(int id){\n    threadLocalCounter=id*1000;\n    for(int i=0;i<5;++i){\n        threadLocalCounter++;\n        if(i==3)setError(\"线程\"+std::to_string(id)+\"的错误信息\");\n        std::cout<<\"线程\"<<id<<\": counter=\"<<threadLocalCounter\n                 <<\", random=\"<<randomInt(1,100)<<\"\\n\";\n    }\n    std::cout<<\"线程\"<<id<<\" lastError: \"<<getError()<<\"\\n\";\n}\n\nclass ThreadLocalResource{\npublic:\n    ThreadLocalResource(){std::cout<<\"线程\"<<std::this_thread::get_id()<<\" 资源构造\\n\";}\n    ~ThreadLocalResource(){std::cout<<\"线程\"<<std::this_thread::get_id()<<\" 资源析构\\n\";}\n    void doSomething(){std::cout<<\"线程\"<<std::this_thread::get_id()<<\" 使用资源\\n\";}\n};\n\nthread_local ThreadLocalResource tlsResource;\n\nvoid useResource(){\n    tlsResource.doSomething();\n}\n\nint main(){\n    std::cout<<\"主线程开始\\n\";\n    useResource();\n\n    std::vector<std::thread>threads;\n    for(int i=0;i<3;++i)threads.emplace_back(threadWork,i);\n    for(auto&t:threads)t.join();\n\n    std::cout<<\"\\n主线程counter=\"<<threadLocalCounter<<\" (不是0+1000+5，因为TLS独立)\\n\";\n    std::cout<<\"主线程lastError=\"<<getError()<<\" (主线程没调用setError所以是空)\\n\";\n    return 0;\n}\n```\n\n重要特性：\n1. 每个线程第一次访问thread_local变量时才会初始化（不是程序启动时）\n2. 线程退出时，该线程的thread_local对象会被析构\n3. thread_local可以和static/extern结合（文件级、类static、局部）\n4. 全局/类static的thread_local在所有线程都有实例；函数内的thread_local也是每线程独立\n\n注意坑：\n- DLL中使用thread_local在Windows XP等老系统有问题（但现代系统没问题）\n- 对thread_local变量取地址，得到的是当前线程实例的地址，不同线程取地址结果不同\n- 不要让thread_local对象的析构函数依赖其他thread_local对象（析构顺序不确定）"
})

data.append({
    "instruction": "并行for_each实现：将区间分割成多个块，用多线程并行处理每个块，支持任意迭代器和可调用对象，最后合并结果",
    "input": "",
    "output": "并行算法可以充分利用多核CPU。parallel_for_each把数据分成N块，每块用一个线程处理。\n\n设计要点：\n1. 确定线程数：hardware_concurrency()，不要太多（线程切换有开销）也不要太少\n2. 分块策略：简单地按元素数平均分割，或者用动态任务窃取（更复杂但负载更均衡）。先实现简单的静态分块。\n3. 迭代器类型：如果是随机访问迭代器可以直接算偏移；否则只能推进。\n4. 异常处理：工作线程中的异常要捕获传递回主线程\n\n```cpp\n#include <iostream>\n#include <vector>\n#include <thread>\n#include <future>\n#include <algorithm>\n#include <stdexcept>\n#include <chrono>\n#include <numeric>\n\ntemplate<typename Iterator,typename Func>\nvoid parallelForEach(Iterator begin,Iterator end,Func func,size_t minPerThread=1000){\n    const size_t total=std::distance(begin,end);\n    if(total==0)return;\n\n    const size_t hwThreads=std::thread::hardware_concurrency();\n    const size_t numThreads=std::min(hwThreads==0?2:hwThreads,(total+minPerThread-1)/minPerThread);\n    const size_t blockSize=total/numThreads;\n\n    std::vector<std::future<void>>futures;\n    std::exception_ptr firstException;\n    std::mutex exMtx;\n\n    Iterator blockStart=begin;\n    for(size_t i=0;i<numThreads;++i){\n        Iterator blockEnd=blockStart;\n        if(i==numThreads-1)blockEnd=end;\n        else std::advance(blockEnd,blockSize);\n\n        futures.push_back(std::async(std::launch::async,[blockStart,blockEnd,&func,&firstException,&exMtx]{\n            try{\n                for(auto it=blockStart;it!=blockEnd;++it)func(*it);\n            }catch(...){\n                std::lock_guard<std::mutex>l(exMtx);\n                if(!firstException)firstException=std::current_exception();\n            }\n        }));\n\n        blockStart=blockEnd;\n    }\n\n    for(auto&f:futures)f.get();\n    if(firstException)std::rethrow_exception(firstException);\n}\n\nint main(){\n    const size_t N=10000000;\n    std::vector<int>data(N);\n    std::iota(data.begin(),data.end(),0);\n\n    auto t0=std::chrono::high_resolution_clock::now();\n    std::for_each(data.begin(),data.end(),[](int&x){x=(int)std::sqrt(x)*2+1;});\n    auto t1=std::chrono::high_resolution_clock::now();\n    std::cout<<\"串行: \"<<std::chrono::duration<double,std::milli>(t1-t0).count()<<\"ms\\n\";\n\n    std::iota(data.begin(),data.end(),0);\n    t0=std::chrono::high_resolution_clock::now();\n    parallelForEach(data.begin(),data.end(),[](int&x){x=(int)std::sqrt(x)*2+1;});\n    t1=std::chrono::high_resolution_clock::now();\n    std::cout<<\"并行: \"<<std::chrono::duration<double,std::milli>(t1-t0).count()<<\"ms\\n\";\n\n    long long sum=0;\n    parallelForEach(data.begin(),data.end(),[&sum](int x){\n        sum+=x;\n    });\n    std::cout<<\"sum=\"<<sum<<\" (注意这里有竞态!因为lambda捕获引用多线程写sum)\\n\";\n\n    return 0;\n}\n```\n\n注意：\n1. 最后一块处理剩余元素（total不一定整除numThreads）\n2. 异常安全：任何线程抛出异常，先存第一个异常，所有线程结束后重新抛出\n3. 用std::async而不是裸thread，方便获取future等待完成\n4. minPerThread避免数据很少时创建太多线程\n5. 示例最后那个sum有竞态条件！因为多个线程同时累加sum需要atomic或mutex，这是演示为什么并行代码要小心共享状态。正确的并行求和应该每个线程算部分和最后合并。\n\n进阶：可以用std::execution::par（C++17 <execution>），编译器自动并行化，但自己实现可以理解原理。"
})

data.append({
    "instruction": "死锁演示与避免：构造一个必然死锁的例子（哲学家就餐问题），然后用std::scoped_lock（C++17）同时加锁避免死锁，解释死锁四个必要条件",
    "input": "",
    "output": "死锁是两个或多个线程互相持有对方需要的锁，永远等待下去。\n\n死锁四个必要条件（Coffman条件）：\n1. 互斥：资源同一时间只能被一个线程持有\n2. 占有并等待：线程持有资源同时等待其他资源\n3. 不可抢占：资源只能被持有者主动释放\n4. 循环等待：存在线程-资源的环形等待链\n\n破坏任一条件即可避免死锁。\n\n经典例子：哲学家就餐。5个哲学家围坐，左右各一根筷子。哲学家思考→饿了→拿左筷子→拿右筷子→吃饭→放下筷子。如果每个人都拿起了左筷子等待右筷子，就死锁了。\n\n解决方案：\n- 方法1：破坏循环等待——按全局顺序加锁（比如按筷子编号，先拿小编号再拿大编号，最后一个人反着来？或者用scoped_lock同时加多个锁）\n- 方法2：破坏占有并等待——同时拿起两根筷子，要么拿到要么不拿\n- 方法3：引入服务员（仲裁者），最多允许4个哲学家同时拿筷子\n\n用std::scoped_lock（C++17）可以原子地同时锁定多个mutex，不会死锁。\n\n```cpp\n#include <iostream>\n#include <thread>\n#include <mutex>\n#include <vector>\n#include <chrono>\n#include <random>\n\nvoid deadlockDemo(){\n    std::cout<<\"=== 死锁演示(会永久卡住，所以注释掉了) ===\\n\";\n    // std::mutex m1,m2;\n    // std::thread t1([&]{std::lock_guard<std::mutex>l1(m1);std::this_thread::sleep_for(std::chrono::milliseconds(100));std::lock_guard<std::mutex>l2(m2);});\n    // std::thread t2([&]{std::lock_guard<std::mutex>l2(m2);std::this_thread::sleep_for(std::chrono::milliseconds(100));std::lock_guard<std::mutex>l1(m1);});\n    // t1.join();t2.join();\n    std::cout<<\"线程1持有m1等m2，线程2持有m2等m1 = 死锁!\\n\\n\";\n}\n\nvoid diningPhilosophers(){\n    const int N=5;\n    std::vector<std::mutex>chopsticks(N);\n    std::atomic<bool>running{true};\n    std::atomic<int>meals{0};\n\n    auto philosopher=[&](int id){\n        std::mt19937 rng(id);\n        int left=id,right=(id+1)%N;\n\n        while(running){\n            std::this_thread::sleep_for(std::chrono::milliseconds(rng()%10));\n\n            if(id==N-1)std::swap(left,right);\n\n            {\n                std::scoped_lock lock(chopsticks[left],chopsticks[right]);\n                meals++;\n                std::this_thread::sleep_for(std::chrono::milliseconds(rng()%20));\n            }\n        }\n    };\n\n    std::vector<std::thread>philosophers;\n    for(int i=0;i<N;++i)philosophers.emplace_back(philosopher,i);\n\n    std::this_thread::sleep_for(std::chrono::seconds(1));\n    running=false;\n    for(auto&t:philosophers)t.join();\n    std::cout<<\"1秒内吃了\"<<meals<<\"次饭，没有死锁\\n\";\n}\n\nvoid bankTransfer(std::mutex&m1,int&a,std::mutex&m2,int&b,int amount){\n    std::scoped_lock lock(m1,m2);\n    if(a>=amount){a-=amount;b+=amount;}\n}\n\nint main(){\n    deadlockDemo();\n\n    std::cout<<\"=== 哲学家就餐(避免死锁) ===\\n\";\n    diningPhilosophers();\n\n    std::cout<<\"\\n=== 银行转账(避免死锁) ===\\n\";\n    std::mutex ma,mb;\n    int acctA=1000,acctB=1000;\n    std::vector<std::thread>threads;\n    for(int i=0;i<100;++i){\n        threads.emplace_back([&]{\n            for(int j=0;j<10;++j)bankTransfer(ma,acctA,mb,acctB,1);\n        });\n        threads.emplace_back([&]{\n            for(int j=0;j<10;++j)bankTransfer(mb,acctB,ma,acctA,1);\n        });\n    }\n    for(auto&t:threads)t.join();\n    std::cout<<\"A=\"<<acctA<<\" B=\"<<acctB<<\" 总和=\"<<acctA+acctB<<\" (应为2000)\\n\";\n    return 0;\n}\n```\n\n关键要点：\n1. std::scoped_lock（C++17）/std::lock（C++11）原子地锁定多个mutex，内部使用死锁避免算法（按某个一致顺序获取，可能尝试回退重试）\n2. 哲学家问题中：让最后一个哲学家先拿右边筷子再拿左边，破坏了循环等待条件\n3. 银行转账是典型场景：从A转钱到B需要锁两个账户，如果两个转账方向相反就会死锁，用scoped_lock解决\n4. 其他避免死锁原则：\n   - 尽量避免同时持有多个锁\n   - 如果必须，保证所有线程按相同顺序获取锁\n   - 使用std::lock/scoped_lock\n   - 加锁带超时try_lock_for（但不总是可行）"
})

data.append({
    "instruction": "异步延迟任务调度器：支持提交延迟任务（多少毫秒后执行）、周期性任务，支持取消任务，用时间轮优先队列实现",
    "input": "",
    "output": "任务调度器需要在指定时间点执行任务，是很多框架的基础组件。\n\n实现思路：\n1. 后台线程循环等待\n2. 用优先队列（最小堆）按执行时间排序，最早的任务在顶\n3. 队列为空时永久等待；有任务时wait_for到最近的执行时间\n4. 到达时间执行任务\n5. 周期性任务执行后重新计算下次执行时间放回队列\n6. 任务ID支持取消\n\n关键点：新任务加入时如果比当前堆顶还早，需要唤醒线程重新计算等待时间。\n\n```cpp\n#include <iostream>\n#include <thread>\n#include <mutex>\n#include <condition_variable>\n#include <queue>\n#include <chrono>\n#include <atomic>\n#include <functional>\n#include <unordered_set>\n\nusing Clock=std::chrono::steady_clock;\nusing TimePoint=Clock::time_point;\n\nstruct Task{\n    uint64_t id;\n    TimePoint time;\n    std::chrono::milliseconds period;\n    std::function<void()>func;\n    bool cancelled=false;\n\n    bool operator>(const Task&o)const{return time>o.time;}\n};\n\nclass Scheduler{\n    std::priority_queue<Task,std::vector<Task>,std::greater<Task>>pq;\n    std::mutex mtx;\n    std::condition_variable cv;\n    std::atomic<bool>running{false};\n    std::thread worker;\n    std::atomic<uint64_t>nextId{1};\n    std::unordered_set<uint64_t>cancelled;\n\n    void run(){\n        while(running){\n            std::function<void()>f;\n            {\n                std::unique_lock<std::mutex>l(mtx);\n                while(running&&pq.empty())cv.wait(l);\n                if(!running)return;\n\n                auto now=Clock::now();\n                auto&top=const_cast<Task&>(pq.top());\n\n                if(top.cancelled||cancelled.count(top.id)){\n                    pq.pop();cancelled.erase(top.id);continue;\n                }\n\n                if(top.time>now){\n                    cv.wait_until(l,top.time);\n                    continue;\n                }\n\n                Task t=top;pq.pop();\n                f=t.func;\n\n                if(t.period.count()>0){\n                    t.time=now+t.period;\n                    pq.push(t);\n                }\n            }\n            if(f)f();\n        }\n    }\n\npublic:\n    void start(){\n        if(running.exchange(true))return;\n        worker=std::thread(&Scheduler::run,this);\n    }\n\n    void stop(){\n        running=false;cv.notify_all();\n        if(worker.joinable())worker.join();\n    }\n\n    ~Scheduler(){stop();}\n\n    uint64_t scheduleAt(std::function<void()>f,TimePoint tp){\n        uint64_t id=nextId++;\n        {\n            std::lock_guard<std::mutex>l(mtx);\n            bool needNotify=pq.empty()||tp<pq.top().time;\n            pq.push({id,tp,std::chrono::milliseconds(0),std::move(f),false});\n            if(needNotify)cv.notify_one();\n        }\n        return id;\n    }\n\n    uint64_t scheduleAfter(std::function<void()>f,std::chrono::milliseconds delay){\n        return scheduleAt(std::move(f),Clock::now()+delay);\n    }\n\n    uint64_t scheduleEvery(std::function<void()>f,std::chrono::milliseconds period,std::chrono::milliseconds initialDelay=std::chrono::milliseconds(0)){\n        return scheduleAt(std::move(f),Clock::now()+initialDelay+period,period);\n    }\n\n    uint64_t scheduleAt(std::function<void()>f,TimePoint tp,std::chrono::milliseconds period){\n        uint64_t id=nextId++;\n        {\n            std::lock_guard<std::mutex>l(mtx);\n            pq.push({id,tp,period,std::move(f),false});\n            cv.notify_one();\n        }\n        return id;\n    }\n\n    void cancel(uint64_t id){\n        std::lock_guard<std::mutex>l(mtx);\n        cancelled.insert(id);\n    }\n};\n\nint main(){\n    Scheduler sched;sched.start();\n\n    std::cout<<\"开始调度...\\n\";\n    sched.scheduleAfter([]{std::cout<<\"1秒后执行\\n\";},std::chrono::seconds(1));\n    sched.scheduleAfter([]{std::cout<<\"2秒后执行\\n\";},std::chrono::seconds(2));\n    auto id=sched.scheduleEvery([]{\n        std::cout<<\"周期任务 每500ms\\n\";\n    },std::chrono::milliseconds(500),std::chrono::milliseconds(100));\n\n    sched.scheduleAfter([&]{\n        std::cout<<\"取消周期任务\\n\";\n        sched.cancel(id);\n    },std::chrono::seconds(3));\n\n    std::this_thread::sleep_for(std::chrono::seconds(4));\n    sched.stop();\n    std::cout<<\"调度器停止\\n\";\n    return 0;\n}\n```\n\n要点：\n1. 优先队列（最小堆）按执行时间排序，最早任务先执行\n2. wait_until等待到下一个任务时间，不用忙等\n3. 新任务比堆顶早时需要notify_one，防止线程在等一个更晚的时间而错过新任务\n4. 周期性任务执行后重新计算时间入队\n5. 取消用cancelled集合标记，真正执行时检查（简单的协作式取消）；更高级可以从堆中删除但priority_queue不支持高效删除，标记法简单可行\n6. steady_clock不受系统时间调整影响，适合计时"
})

