data.append({
    "instruction": "TCP客户端实现：连接服务器、发送数据、接收响应，支持连接超时设置、自动重连机制",
    "input": "",
    "output": "TCP客户端流程：socket→connect→send/recv→close。\n\n需要解决的问题：\n1. connect默认超时可能很长（几十秒），怎么设置短一点？阻塞socket很难直接设，可以临时设非阻塞connect，用select等待可写判断连接结果，带超时\n2. 自动重连：连接断开后隔一段时间重试，有次数限制\n3. recv/send完整数据\n\n```cpp\n#ifdef _WIN32\n#include <winsock2.h>\n#include <ws2tcpip.h>\n#pragma comment(lib,\"ws2_32.lib\")\n#else\n#include <sys/socket.h>\n#include <netinet/in.h>\n#include <arpa/inet.h>\n#include <unistd.h>\n#include <fcntl.h>\n#include <errno.h>\n#include <sys/select.h>\nusing SOCKET=int;constexpr SOCKET INVALID_SOCKET=-1;constexpr int SOCKET_ERROR=-1;\n#define closesocket close\n#endif\n#include <iostream>\n#include <string>\n#include <chrono>\n#include <thread>\n\n#ifdef _WIN32\nvoid setNonBlocking(SOCKET s,bool nb){u_long v=nb?1:0;ioctlsocket(s,FIONBIO,&v);}\nint getLastError(){return WSAGetLastError();}\nconst int EWOULDBLOCK=WSAEWOULDBLOCK;\n#else\nvoid setNonBlocking(SOCKET s,bool nb){int f=fcntl(s,F_GETFL,0);fcntl(s,F_SETFL,nb?(f|O_NONBLOCK):(f&~O_NONBLOCK));}\nint getLastError(){return errno;}\n#endif\n\nbool connectWithTimeout(SOCKET s,const char*ip,int port,int timeoutMs){\n    sockaddr_in addr{};\n    addr.sin_family=AF_INET;addr.sin_port=htons(port);\n    inet_pton(AF_INET,ip,&addr.sin_addr);\n\n    setNonBlocking(s,true);\n    int ret=connect(s,(sockaddr*)&addr,sizeof(addr));\n#ifdef _WIN32\n    if(ret==SOCKET_ERROR&&getLastError()!=WSAEWOULDBLOCK){\n#else\n    if(ret<0&&errno!=EINPROGRESS){\n#endif\n        setNonBlocking(s,false);\n        return false;\n    }\n\n    fd_set wfds;FD_ZERO(&wfds);FD_SET(s,&wfds);\n    timeval tv;tv.tv_sec=timeoutMs/1000;tv.tv_usec=(timeoutMs%1000)*1000;\n\n    int sel=select((int)s+1,nullptr,&wfds,nullptr,&tv);\n    setNonBlocking(s,false);\n\n    if(sel>0){\n        int err=0;socklen_t len=sizeof(err);\n        getsockopt(s,SOL_SOCKET,SO_ERROR,(char*)&err,&len);\n        return err==0;\n    }\n    return false;\n}\n\nbool sendAll(SOCKET s,const char*d,size_t l){\n    while(l>0){int sent=send(s,d,(int)l,0);if(sent<=0)return false;d+=sent;l-=sent;}\n    return true;\n}\n\nint recvWithTimeout(SOCKET s,char*buf,int len,int timeoutMs){\n    fd_set rfds;FD_ZERO(&rfds);FD_SET(s,&rfds);\n    timeval tv;tv.tv_sec=timeoutMs/1000;tv.tv_usec=(timeoutMs%1000)*1000;\n    int sel=select((int)s+1,&rfds,nullptr,nullptr,&tv);\n    if(sel<=0)return sel;\n    return recv(s,buf,len,0);\n}\n\nclass TcpClient{\n    SOCKET sock=INVALID_SOCKET;\n    std::string ip;int port;\npublic:\n    TcpClient(const std::string&i,int p):ip(i),port(p){}\n    ~TcpClient(){close();}\n\n    bool connect(int timeoutMs=3000){\n        close();\n        sock=socket(AF_INET,SOCK_STREAM,0);\n        if(sock==INVALID_SOCKET)return false;\n        if(connectWithTimeout(sock,ip.c_str(),port,timeoutMs))return true;\n        closesocket(sock);sock=INVALID_SOCKET;return false;\n    }\n\n    void close(){if(sock!=INVALID_SOCKET){closesocket(sock);sock=INVALID_SOCKET;}}\n\n    bool send(const std::string&d){return sock!=INVALID_SOCKET&&sendAll(sock,d.data(),d.size());}\n\n    std::string recv(int timeoutMs=3000){\n        char buf[4096];std::string result;\n        int n=recvWithTimeout(sock,buf,sizeof(buf),timeoutMs);\n        if(n>0)result.assign(buf,n);\n        return result;\n    }\n\n    bool isConnected(){return sock!=INVALID_SOCKET;}\n\n    bool connectWithRetry(int maxRetries=3,int retryDelayMs=1000,int timeoutMs=3000){\n        for(int i=0;i<maxRetries;++i){\n            std::cout<<\"尝试连接(\"<<(i+1)<<\"/\"<<maxRetries<<\")...\\n\";\n            if(connect(timeoutMs)){std::cout<<\"连接成功\\n\";return true;}\n            if(i<maxRetries-1)std::this_thread::sleep_for(std::chrono::milliseconds(retryDelayMs));\n        }\n        return false;\n    }\n};\n\nint main(){\n#ifdef _WIN32\n    WSADATA wd;WSAStartup(MAKEWORD(2,2),&wd);\n#endif\n\n    TcpClient client(\"127.0.0.1\",8080);\n    if(client.connectWithRetry(2,500,1000)){\n        client.send(\"GET / HTTP/1.0\\r\\n\\r\\n\");\n        std::string resp=client.recv(2000);\n        std::cout<<\"收到响应\"<<resp.size()<<\"字节\\n\";\n        std::cout<<resp.substr(0,200)<<\"\\n\";\n    }else{\n        std::cout<<\"连接失败(确保先启动HTTP服务器)\\n\";\n    }\n\n#ifdef _WIN32\n    WSACleanup();\n#endif\n    return 0;\n}\n```\n\n要点：\n1. 非阻塞connect+select实现连接超时：这是标准做法，阻塞connect超时由OS控制不好改\n2. 连接成功后要getsockopt检查SO_ERROR，因为select返回可写可能是连接出错\n3. select等待可读实现接收超时\n4. 指数退避或固定间隔重试\n5. 注意Windows和Linux的非阻塞设置、错误码差异\n6. sendAll/recvAll处理TCP流边界"
})

data.append({
    "instruction": "UDP广播与组播：实现UDP发送广播消息（全网段）和接收，以及组播（多播）发送接收",
    "input": "",
    "output": "UDP是无连接协议，不需要connect，适合广播/组播。\n\n广播（Broadcast）：发送到局域网内所有主机，目标地址是255.255.255.255或子网定向广播地址。需要设置SO_BROADCAST选项。所有监听该端口的主机都能收到。\n\n组播（Multicast）：发送到一个组播地址（224.0.0.0-239.255.255.255），只有加入该组的主机才能接收。比广播更高效，不会打扰不感兴趣的主机。\n\n关键socket选项：\n- SO_BROADCAST：允许发送广播\n- IP_ADD_MEMBERSHIP：加入组播组\n- IP_MULTICAST_TTL：组播TTL（控制传播跳数，0本地主机、1子网、32站点、64地区、128大陆、255全球）\n- IP_MULTICAST_LOOP：是否回环到本机\n\n```cpp\n#ifdef _WIN32\n#include <winsock2.h>\n#include <ws2tcpip.h>\n#pragma comment(lib,\"ws2_32.lib\")\n#else\n#include <sys/socket.h>\n#include <netinet/in.h>\n#include <arpa/inet.h>\n#include <unistd.h>\n#include <net/if.h>\nusing SOCKET=int;constexpr SOCKET INVALID_SOCKET=-1;constexpr int SOCKET_ERROR=-1;\n#define closesocket close\n#endif\n#include <iostream>\n#include <string>\n#include <thread>\n\nSOCKET createUdpSocket(){\n    SOCKET s=socket(AF_INET,SOCK_DGRAM,0);\n#ifdef _WIN32\n    char opt=1;\n#else\n    int opt=1;\n#endif\n    setsockopt(s,SOL_SOCKET,SO_REUSEADDR,(const char*)&opt,sizeof(opt));\n    return s;\n}\n\nvoid broadcastSender(int port,const std::string&msg){\n    SOCKET s=createUdpSocket();\n#ifdef _WIN32\n    BOOL bcast=TRUE;\n#else\n    int bcast=1;\n#endif\n    setsockopt(s,SOL_SOCKET,SO_BROADCAST,(const char*)&bcast,sizeof(bcast));\n\n    sockaddr_in addr{};\n    addr.sin_family=AF_INET;addr.sin_port=htons(port);\n    addr.sin_addr.s_addr=inet_addr(\"255.255.255.255\");\n\n    sendto(s,msg.data(),(int)msg.size(),0,(sockaddr*)&addr,sizeof(addr));\n    std::cout<<\"广播发送: \"<<msg<<\"\\n\";\n    closesocket(s);\n}\n\nvoid broadcastReceiver(int port){\n    SOCKET s=createUdpSocket();\n    sockaddr_in addr{};\n    addr.sin_family=AF_INET;addr.sin_port=htons(port);addr.sin_addr.s_addr=INADDR_ANY;\n    bind(s,(sockaddr*)&addr,sizeof(addr));\n\n    char buf[1024];\n    sockaddr_in from;int fromLen=sizeof(from);\n    int n=recvfrom(s,buf,sizeof(buf),0,(sockaddr*)&from,&fromLen);\n    if(n>0)std::cout<<\"广播接收: \"<<std::string(buf,n)<<\" from \"<<inet_ntoa(from.sin_addr)<<\"\\n\";\n    closesocket(s);\n}\n\nvoid multicastSender(const char*multicastIp,int port,const std::string&msg){\n    SOCKET s=createUdpSocket();\n    int ttl=1;\n    setsockopt(s,IPPROTO_IP,IP_MULTICAST_TTL,(const char*)&ttl,sizeof(ttl));\n\n    sockaddr_in addr{};\n    addr.sin_family=AF_INET;addr.sin_port=htons(port);\n    inet_pton(AF_INET,multicastIp,&addr.sin_addr);\n\n    sendto(s,msg.data(),(int)msg.size(),0,(sockaddr*)&addr,sizeof(addr));\n    std::cout<<\"组播发送: \"<<msg<<\"\\n\";\n    closesocket(s);\n}\n\nvoid multicastReceiver(const char*multicastIp,int port){\n    SOCKET s=createUdpSocket();\n    sockaddr_in addr{};\n    addr.sin_family=AF_INET;addr.sin_port=htons(port);addr.sin_addr.s_addr=INADDR_ANY;\n    bind(s,(sockaddr*)&addr,sizeof(addr));\n\n    ip_mreq mreq{};\n    inet_pton(AF_INET,multicastIp,&mreq.imr_multiaddr);\n    mreq.imr_interface.s_addr=INADDR_ANY;\n    setsockopt(s,IPPROTO_IP,IP_ADD_MEMBERSHIP,(const char*)&mreq,sizeof(mreq));\n\n    char buf[1024];\n    int n=recv(s,buf,sizeof(buf),0);\n    if(n>0)std::cout<<\"组播接收: \"<<std::string(buf,n)<<\"\\n\";\n\n    setsockopt(s,IPPROTO_IP,IP_DROP_MEMBERSHIP,(const char*)&mreq,sizeof(mreq));\n    closesocket(s);\n}\n\nint main(){\n#ifdef _WIN32\n    WSADATA wd;WSAStartup(MAKEWORD(2,2),&wd);\n#endif\n\n    std::cout<<\"=== UDP广播测试 ===\\n\";\n    std::thread r1(broadcastReceiver,9000);\n    std::this_thread::sleep_for(std::chrono::milliseconds(100));\n    broadcastSender(9000,\"Hello Broadcast!\");\n    r1.join();\n\n    std::cout<<\"\\n=== UDP组播测试 ===\\n\";\n    const char*mcastIp=\"239.255.0.1\";\n    std::thread r2(multicastReceiver,mcastIp,9001);\n    std::this_thread::sleep_for(std::chrono::milliseconds(100));\n    multicastSender(mcastIp,9001,\"Hello Multicast!\");\n    r2.join();\n\n#ifdef _WIN32\n    WSACleanup();\n#endif\n    return 0;\n}\n```\n\n要点：\n1. UDP无连接，用sendto/recvfrom指定目标地址和获取发送方地址\n2. SO_BROADCAST必须显式开启才能发送广播\n3. 组播需要IP_ADD_MEMBERSHIP加入组，结束后IP_DROP_MEMBERSHIP离开\n4. TTL控制组播包能跨越多少路由器，本地子网设1就够\n5. SO_REUSEADDR允许多个socket绑定同一端口（多个接收者）\n6. 广播会打扰局域网所有主机，组播只发给感兴趣的，更高效"
})

data.append({
    "instruction": "TCP粘包问题处理：设计一个简单的应用层协议（长度字段+消息体），实现正确的分包，处理半包、粘包情况",
    "input": "",
    "output": "TCP是面向流的协议，没有消息边界。send的\"包\"和recv的\"包\"不是一一对应的：\n- 粘包：多个send被合并成一次recv收到\n- 半包：一个send被分成多次recv收到\n\n必须在应用层设计协议来区分消息边界。常见方案：\n1. 固定长度：每条消息固定N字节，简单但浪费空间\n2. 分隔符：比如\\r\\n结尾（HTTP），但消息体中可能出现分隔符需要转义\n3. 长度字段：固定N字节表示消息长度，后面跟消息体。最常用。\n\n我们用方案3：4字节小端序长度+消息体。\n\n实现要点：\n- 需要一个接收缓冲区，recv到的数据都append进去\n- 每次检查缓冲区：如果长度≥4字节，先读长度；如果总长度≥4+length，就取出完整消息\n- 剩余数据留在缓冲区下次继续处理\n\n```cpp\n#ifdef _WIN32\n#include <winsock2.h>\n#pragma comment(lib,\"ws2_32.lib\")\n#else\n#include <sys/socket.h>\n#include <netinet/in.h>\n#include <arpa/inet.h>\n#include <unistd.h>\nusing SOCKET=int;constexpr SOCKET INVALID_SOCKET=-1;constexpr int SOCKET_ERROR=-1;\n#define closesocket close\n#endif\n#include <iostream>\n#include <string>\n#include <vector>\n#include <cstring>\n#include <thread>\n\nclass LengthPrefixedProtocol{\n    std::vector<char>buffer;\npublic:\n    void feed(const char*data,size_t len){\n        buffer.insert(buffer.end(),data,data+len);\n    }\n\n    bool tryPopMessage(std::string&out){\n        if(buffer.size()<4)return false;\n        uint32_t len;\n        memcpy(&len,buffer.data(),4);\n        len=ntohl(len);\n        if(buffer.size()<4+len)return false;\n        out.assign(buffer.data()+4,len);\n        buffer.erase(buffer.begin(),buffer.begin()+4+len);\n        return true;\n    }\n\n    static std::string encode(const std::string&msg){\n        std::string result;\n        uint32_t len=htonl((uint32_t)msg.size());\n        result.append((char*)&len,4);\n        result+=msg;\n        return result;\n    }\n};\n\nint main(){\n#ifdef _WIN32\n    WSADATA wd;WSAStartup(MAKEWORD(2,2),&wd);\n#endif\n\n    std::cout<<\"=== 模拟粘包/半包测试 ===\\n\";\n\n    LengthPrefixedProtocol proto;\n\n    std::string m1=proto.encode(\"Hello\");\n    std::string m2=proto.encode(\"World\");\n    std::string m3=proto.encode(\"This is a longer message containing more data\");\n\n    std::cout<<\"编码后: m1=\"<<m1.size()<<\"字节, m2=\"<<m2.size()<<\"字节\\n\";\n\n    // 模拟粘包：一次收到两个完整消息\n    std::string combined=m1+m2;\n    proto.feed(combined.data(),combined.size());\n\n    std::string msg;\n    int received=0;\n    while(proto.tryPopMessage(msg)){\n        std::cout<<\"收到消息[\"<<received++<<\"]: \"<<msg<<\"\\n\";\n    }\n\n    // 模拟半包：先收到部分数据\n    proto.feed(m3.data(),5);\n    std::cout<<\"喂5字节后，能取到消息吗？\"<<(proto.tryPopMessage(msg)?\"有:\"没有\")<<\"\\n\";\n\n    // 喂剩下的数据\n    proto.feed(m3.data()+5,m3.size()-5);\n    if(proto.tryPopMessage(msg)){\n        std::cout<<\"喂完所有数据后收到: \"<<msg<<\"\\n\";\n    }\n\n    // 模拟多包粘连+半包\n    std::string big=m1+m2+m3+m1;\n    size_t pos=0;\n    while(pos<big.size()){\n        size_t chunk=std::min(big.size()-pos,(size_t)(rand()%6+2));\n        proto.feed(big.data()+pos,chunk);\n        pos+=chunk;\n        while(proto.tryPopMessage(msg)){\n            std::cout<<\"随机分片后收到: \"<<msg<<\"\\n\";\n        }\n    }\n\n    std::cout<<\"\\n=== 实际socket通信示例（本地回环） ===\\n\";\n    // 简单演示：一对connected socket\n    SOCKET sv[2];\n    // Windows可以用socketpair吗？没有，用TCP监听连接简单演示...\n    // 这里简化说明概念\n    std::cout<<\"实际使用时：\n\";\n    std::cout<<\"1. 发送方: encode消息后send\n\";\n    std::cout<<\"2. 接收方: 循环recv，把数据feed到协议对象\n\";\n    std::cout<<\"3. 循环tryPopMessage直到返回false\n\";\n\n#ifdef _WIN32\n    WSACleanup();\n#endif\n    return 0;\n}\n```\n\n要点：\n1. 网络字节序是大端序（htonl/ntohl转换），保证跨平台兼容\n2. 接收缓冲区必不可少，因为TCP不保证消息边界\n3. 每次recv后循环解析，缓冲区中可能有多条消息\n4. 长度字段必须有足够大：4字节支持最大4GB消息足够用了\n5. 处理顺序：先解析长度，再判断是否有完整消息\n\n实际项目中可以用protobuf/flatbuffers等序列化库，但TCP分包逻辑还是要自己处理，原理相同。"
})

data.append({
    "instruction": "使用select实现多路IO复用：单线程同时处理多个TCP连接，包括监听socket和客户端socket，实现简单的Reactor模式雏形",
    "input": "",
    "output": "一个线程同时处理多个连接怎么实现？多线程每连接一线程在连接数多的时候（比如几千上万）线程切换开销大。IO多路复用允许一个线程等待多个socket中的任意一个就绪。\n\nselect是经典的IO复用模型（还有poll、epoll、kqueue、IOCP等）。工作流程：\n1. 构造fd_set，把要监听的socket放进去\n2. 调用select，阻塞等待直到有socket就绪或超时\n3. select返回后，遍历所有socket检查哪个可读/可写/异常\n4. 处理就绪的socket\n\nselect缺点：\n- 最大fd数量限制（FD_SETSIZE通常64或1024）\n- 每次调用都要遍历所有fd，O(n)复杂度\n- 每次调用需要把fd_set从用户态拷贝到内核态\n\n但跨平台兼容性最好。\n\n```cpp\n#ifdef _WIN32\n#include <winsock2.h>\n#pragma comment(lib,\"ws2_32.lib\")\n#include <ws2tcpip.h>\n#else\n#include <sys/socket.h>\n#include <netinet/in.h>\n#include <arpa/inet.h>\n#include <unistd.h>\n#include <sys/select.h>\nusing SOCKET=int;constexpr SOCKET INVALID_SOCKET=-1;constexpr int SOCKET_ERROR=-1;\n#define closesocket close\n#endif\n#include <iostream>\n#include <vector>\n#include <string>\n#include <algorithm>\n\nconst int PORT=8081;\nconst int MAX_CLIENTS=64;\n\nbool sendAll(SOCKET s,const char*d,size_t l){\n    while(l>0){int sent=send(s,d,(int)l,0);if(sent<=0)return false;d+=sent;l-=sent;}\n    return true;\n}\n\nint main(){\n#ifdef _WIN32\n    WSADATA wd;WSAStartup(MAKEWORD(2,2),&wd);\n#endif\n\n    SOCKET listenSock=socket(AF_INET,SOCK_STREAM,0);\n    int opt=1;setsockopt(listenSock,SOL_SOCKET,SO_REUSEADDR,(const char*)&opt,sizeof(opt));\n    sockaddr_in addr{};addr.sin_family=AF_INET;addr.sin_port=htons(PORT);addr.sin_addr.s_addr=INADDR_ANY;\n    bind(listenSock,(sockaddr*)&addr,sizeof(addr));\n    listen(listenSock,SOMAXCONN);\n\n    std::vector<SOCKET>clients;\n    std::cout<<\"Select-based Echo Server on port \"<<PORT<<\"\\n\";\n\n    while(true){\n        fd_set readfds;FD_ZERO(&readfds);\n        FD_SET(listenSock,&readfds);\n        SOCKET maxFd=listenSock;\n\n        for(SOCKET c:clients){\n            FD_SET(c,&readfds);\n            if(c>maxFd)maxFd=c;\n        }\n\n        timeval tv;tv.tv_sec=1;tv.tv_usec=0;\n        int ret=select((int)maxFd+1,&readfds,nullptr,nullptr,&tv);\n        if(ret<0)break;\n\n        if(FD_ISSET(listenSock,&readfds)){\n            sockaddr_in ca;int calen=sizeof(ca);\n            SOCKET c=accept(listenSock,(sockaddr*)&ca,&calen);\n            if(c!=INVALID_SOCKET&&clients.size()<MAX_CLIENTS){\n                clients.push_back(c);\n                std::cout<<\"新连接: \"<<inet_ntoa(ca.sin_addr)<<\"\\n\";\n                const char*welcome=\"Welcome to Echo Server!\\n\";\n                send(c,welcome,(int)strlen(welcome),0);\n            }else if(c!=INVALID_SOCKET){\n                const char*full=\"Server full\\n\";\n                send(c,full,(int)strlen(full),0);\n                closesocket(c);\n            }\n        }\n\n        std::vector<SOCKET>toClose;\n        for(SOCKET c:clients){\n            if(FD_ISSET(c,&readfds)){\n                char buf[4096];\n                int n=recv(c,buf,sizeof(buf),0);\n                if(n<=0){\n                    toClose.push_back(c);\n                    continue;\n                }\n                std::cout<<\"收到\"<<n<<\"字节\";\n                sendAll(c,buf,n);\n            }\n        }\n\n        for(SOCKET c:toClose){\n            std::cout<<\"连接断开\\n\";\n            closesocket(c);\n            clients.erase(std::remove(clients.begin(),clients.end(),c),clients.end());\n        }\n    }\n\n    closesocket(listenSock);\n#ifdef _WIN32\n    WSACleanup();\n#endif\n    return 0;\n}\n```\n\nReactor模式核心思想：\n1. 事件分离器（select）等待事件\n2. 事件发生后分发到对应的处理器\n3. 监听socket有事件→accept\n4. 客户端socket有读事件→recv处理\n\n要点：\n1. 每次select前都要重新初始化fd_set！因为select返回后fd_set会被修改，只保留就绪的fd\n2. 必须记录maxFd，select第一个参数是nfds = maxfd+1（Linux下必须，Windows下可以忽略但最好写）\n3. 客户端断开时recv返回0或-1，要关闭并从clients列表移除\n4. select带超时可以定期做一些空闲任务（比如心跳检测）\n\n进阶：poll没有fd数量限制但还是O(n)；Linux epoll、Windows IOCP是事件驱动、O(1)复杂度，适合高并发服务器。"
})

data.append({
    "instruction": "简单聊天室服务器：多个客户端连接到服务器，任何客户端发送消息，服务器广播给所有其他客户端。用select或多线程实现",
    "input": "",
    "output": "聊天室是广播模式的典型应用。核心功能：\n1. 新客户端连接加入\n2. 客户端消息转发给所有人\n3. 客户端断开清理\n4. 处理部分发送（send返回小于请求长度）\n\n每个客户端需要发送缓冲区吗？如果send因为缓冲区满只发了部分，需要把剩余的存起来下次写事件触发时继续发。简单版假设send总能一次发完（本地测试没问题）。\n\n```cpp\n#ifdef _WIN32\n#include <winsock2.h>\n#pragma comment(lib,\"ws2_32.lib\")\n#else\n#include <sys/socket.h>\n#include <netinet/in.h>\n#include <arpa/inet.h>\n#include <unistd.h>\nusing SOCKET=int;constexpr SOCKET INVALID_SOCKET=-1;\n#define closesocket close\n#endif\n#include <iostream>\n#include <vector>\n#include <string>\n#include <algorithm>\n#include <mutex>\n\nconst int PORT=8082;\nstd::mutex coutMtx;\n\nvoid broadcast(const std::vector<SOCKET>&clients,SOCKET from,const std::string&msg){\n    std::string packet=\"client\"+std::to_string(from)+\": \"+msg+\"\\n\";\n    for(SOCKET c:clients){\n        if(c!=from)send(c,packet.data(),(int)packet.size(),0);\n    }\n}\n\nint main(){\n#ifdef _WIN32\n    WSADATA wd;WSAStartup(MAKEWORD(2,2),&wd);\n#endif\n\n    SOCKET ls=socket(AF_INET,SOCK_STREAM,0);\n    int opt=1;setsockopt(ls,SOL_SOCKET,SO_REUSEADDR,(const char*)&opt,sizeof(opt));\n    sockaddr_in addr{};addr.sin_family=AF_INET;addr.sin_port=htons(PORT);addr.sin_addr.s_addr=INADDR_ANY;\n    bind(ls,(sockaddr*)&addr,sizeof(addr));listen(ls,SOMAXCONN);\n\n    std::vector<std::thread>threads;\n    std::vector<SOCKET>clients;\n    std::mutex clientsMtx;\n\n    auto handleClient=[&](SOCKET c){\n        char buf[4096];\n        while(true){\n            int n=recv(c,buf,sizeof(buf)-1,0);\n            if(n<=0)break;\n            buf[n]=0;\n            std::string msg(buf);\n            if(!msg.empty()&&msg.back()=='\\n')msg.pop_back();\n            if(!msg.empty()&&msg.back()=='\\r')msg.pop_back();\n            {\n                std::lock_guard<std::mutex>lk(clientsMtx);\n                broadcast(clients,c,msg);\n            }\n            std::lock_guard<std::mutex>l(coutMtx);\n            std::cout<<\"client\"<<c<<\": \"<<msg<<\"\\n\";\n        }\n        {\n            std::lock_guard<std::mutex>lk(clientsMtx);\n            clients.erase(std::remove(clients.begin(),clients.end(),c),clients.end());\n        }\n        closesocket(c);\n    };\n\n    std::cout<<\"Chat room on port \"<<PORT<<\" (use telnet to connect)\\n\";\n\n    while(true){\n        sockaddr_in ca;int calen=sizeof(ca);\n        SOCKET c=accept(ls,(sockaddr*)&ca,&calen);\n        if(c==INVALID_SOCKET)continue;\n        {\n            std::lock_guard<std::mutex>lk(clientsMtx);\n            clients.push_back(c);\n        }\n        threads.emplace_back(handleClient,c);\n        threads.back().detach();\n        std::string welcome=\"欢迎进入聊天室，当前\"+std::to_string(clients.size())+\"人\\n\";\n        send(c,welcome.data(),(int)welcome.size(),0);\n        {\n            std::lock_guard<std::mutex>lk(clientsMtx);\n            broadcast(clients,c,\"加入了聊天室\");\n        }\n    }\n\n    closesocket(ls);\n#ifdef _WIN32\n    WSACleanup();\n#endif\n    return 0;\n}\n```\n\n这个实现用多线程每连接一线程，简单直观。用mutex保护clients列表因为accept线程和客户端线程都可能访问。\n\n思考改进：\n1. 发送缓冲区：因为send可能返回部分发送，需要为每个socket准备一个outgoing buffer，写事件触发时继续发送\n2. 用户名：客户端连接时可以先输入用户名，消息带用户名而不是socket号\n3. 用select/epoll单线程处理大量连接，避免线程开销\n4. 心跳/超时：长时间无消息断开\n5. 消息编码：同样要考虑TCP粘包，可以用换行分隔（简单聊天常用）\n\n测试方法：启动后开两个telnet 127.0.0.1 8082，一个发消息另一个能看到。"
})

data.append({
    "instruction": "socket非阻塞模式与connect超时：将socket设置为非阻塞模式，实现带超时的connect，并理解非阻塞IO的读写模式",
    "input": "",
    "output": "阻塞模式下，connect、recv、send都会阻塞线程直到完成。非阻塞模式下这些调用会立即返回，如果操作无法立刻完成会返回错误（EWOULDBLOCK/EAGAIN），需要配合select/poll/epoll来等待就绪。\n\n非阻塞connect是实现超时连接的唯一方式。步骤：\n1. 创建socket\n2. 设置非阻塞\n3. connect：立即返回EINPROGRESS表示正在连接\n4. select监听socket可写\n5. 如果select超时→连接超时\n6. 如果可写，检查SO_ERROR：0表示成功，否则失败\n\n非阻塞IO读写模式：\n- 读：返回-1且errno==EAGAIN/EWOULDBLOCK表示当前没数据，下次再读；返回0表示连接关闭\n- 写：返回-1且errno==EAGAIN表示发送缓冲区满了，等下次可写事件；返回值小于要发长度表示部分发送\n\n```cpp\n#ifdef _WIN32\n#include <winsock2.h>\n#include <ws2tcpip.h>\n#pragma comment(lib,\"ws2_32.lib\")\n#else\n#include <sys/socket.h>\n#include <netinet/in.h>\n#include <arpa/inet.h>\n#include <unistd.h>\n#include <fcntl.h>\n#include <errno.h>\n#include <sys/select.h>\nusing SOCKET=int;constexpr SOCKET INVALID_SOCKET=-1;constexpr int SOCKET_ERROR=-1;\n#define closesocket close\n#endif\n#include <iostream>\n#include <chrono>\n\n#ifdef _WIN32\nvoid setNonBlocking(SOCKET s,bool nb){u_long v=nb?1:0;ioctlsocket(s,FIONBIO,&v);}\nconst int WOULDBLOCK=WSAEWOULDBLOCK;\nconst int INPROGRESS=WSAEWOULDBLOCK;\n#else\nvoid setNonBlocking(SOCKET s,bool nb){int f=fcntl(s,F_GETFL,0);fcntl(s,F_SETFL,nb?(f|O_NONBLOCK):(f&~O_NONBLOCK));}\nconst int WOULDBLOCK=EWOULDBLOCK;\nconst int INPROGRESS=EINPROGRESS;\n#endif\n\nbool connectTimeout(SOCKET s,const char*ip,int port,int timeoutMs){\n    sockaddr_in addr{};addr.sin_family=AF_INET;addr.sin_port=htons(port);\n    inet_pton(AF_INET,ip,&addr.sin_addr);\n\n    setNonBlocking(s,true);\n    int r=connect(s,(sockaddr*)&addr,sizeof(addr));\n    if(r==0){\n        setNonBlocking(s,false);\n        return true;\n    }\n#ifdef _WIN32\n    if(WSAGetLastError()!=INPROGRESS){setNonBlocking(s,false);return false;}\n#else\n    if(errno!=INPROGRESS){setNonBlocking(s,false);return false;}\n#endif\n\n    fd_set wfds;FD_ZERO(&wfds);FD_SET(s,&wfds);\n    timeval tv;tv.tv_sec=timeoutMs/1000;tv.tv_usec=(timeoutMs%1000)*1000;\n\n    int sel=select((int)s+1,nullptr,&wfds,nullptr,&tv);\n    if(sel<=0){setNonBlocking(s,false);return false;}\n\n    int err=0;socklen_t len=sizeof(err);\n    getsockopt(s,SOL_SOCKET,SO_ERROR,(char*)&err,&len);\n    setNonBlocking(s,false);\n    return err==0;\n}\n\nint main(){\n#ifdef _WIN32\n    WSADATA wd;WSAStartup(MAKEWORD(2,2),&wd);\n#endif\n\n    SOCKET s=socket(AF_INET,SOCK_STREAM,0);\n\n    std::cout<<\"连接不可达地址(测试超时)...\\n\";\n    auto t0=std::chrono::steady_clock::now();\n    bool ok=connectTimeout(s,\"10.255.255.1\",80,2000);\n    auto t1=std::chrono::steady_clock::now();\n    double ms=std::chrono::duration<double,std::milli>(t1-t0).count();\n    std::cout<<\"结果:\"<<(ok?\"成功\":\"失败\")<<\" 耗时:\"<<ms<<\"ms\\n\";\n    closesocket(s);\n\n    s=socket(AF_INET,SOCK_STREAM,0);\n    std::cout<<\"\\n连接百度(80端口)...\\n\";\n    t0=std::chrono::steady_clock::now();\n    ok=connectTimeout(s,\"180.101.50.242\",80,3000);\n    t1=std::chrono::steady_clock::now();\n    ms=std::chrono::duration<double,std::milli>(t1-t0).count();\n    std::cout<<\"结果:\"<<(ok?\"成功\":\"失败\")<<\" 耗时:\"<<ms<<\"ms\\n\";\n    if(ok)send(s,\"HEAD / HTTP/1.0\\r\\nHost: www.baidu.com\\r\\n\\r\\n\",40,0);\n    if(ok){\n        fd_set rfds;FD_ZERO(&rfds);FD_SET(s,&rfds);\n        timeval tv={1,0};\n        if(select((int)s+1,&rfds,nullptr,nullptr,&tv)>0){\n            char buf[512];int n=recv(s,buf,sizeof(buf),0);\n            if(n>0)std::cout<<\"响应\"<<n<<\"字节:\\n\"<<std::string(buf,n).substr(0,200)<<\"...\\n\";\n        }\n    }\n    closesocket(s);\n\n#ifdef _WIN32\n    WSACleanup();\n#endif\n    return 0;\n}\n```\n\n要点：\n1. 非阻塞connect在不同平台的错误码：Windows是WSAEWOULDBLOCK，Linux是EINPROGRESS\n2. 连接成功后socket可写，但可写不代表连接成功——必须检查SO_ERROR\n3. select最后一个参数是timeval，设为NULL是永久等待，0秒0微秒是立即返回（轮询）\n4. 非阻塞IO不会阻塞线程，可以在单线程中处理大量连接（配合IO多路复用）\n5. 实际开发中：如果连接数少（<1000），阻塞+多线程更简单；高并发服务器才需要非阻塞+事件驱动"
})

